  AvgCommunicate_100438_Content_1 = {
    Text = "Keeper, I want to open an art studio at Mythag, with free admission!"
  },
  AvgCommunicate_100438_Content_10 = {
    Text = "I suppose it's acceptable, but..."
  },
  AvgCommunicate_100438_Content_11 = {Text = "But?"},
  AvgCommunicate_100438_Content_12 = {
    Text = "You should pay me a reward. I want cupcakes."
  },
  AvgCommunicate_100438_Content_13 = {Text = "!?"},
  AvgCommunicate_100438_Content_14 = {
    Text = "Pleeease? Pretty please?"
  },
  AvgCommunicate_100438_Content_15 = {
    Text = "A free model, dedicated to helping you achieve the most perfect art! Where else will you find a model this cooperative?"
  },
  AvgCommunicate_100438_Content_16 = {
    Text = "...That's a fair point."
  },
  AvgCommunicate_100438_Content_17 = {
    Text = "See you at the studio tomorrow!"
  },
  AvgCommunicate_100438_Content_2 = {
    Text = "A painting masterclass personally taught by me, and all my prized art supplies will be at your disposal. Aren't you excited?"
  },
  AvgCommunicate_100438_Content_3 = {
    Text = "Is there really such a good deal?"
  },
  AvgCommunicate_100438_Content_4 = {
    Text = "I can't wait!"
  },
  AvgCommunicate_100438_Content_5 = {
    Text = "As a great painter and a seasoned educator, selflessness has always been my most prominent trait. However, you must understand that the creation of any magnificent art requires a certain spark of inspiration..."
  },
  AvgCommunicate_100438_Content_6 = {
    Text = "As a small recompense for my teaching, might I ask you to serve as the model for my artwork?"
  },
  AvgCommunicate_100438_Content_7 = {
    Text = "I knew it..."
  },
  AvgCommunicate_100438_Content_8 = {
    Text = "Pleeease? Pretty please?"
  },
  AvgCommunicate_100438_Content_9 = {
    Text = "Free masterclass, free studio space, free art supplies—everything is free!"
  },
  AvgCommunicate_100438_Option_3 = {
    Text = "Is there really such a good deal?"
  },
  AvgCommunicate_100438_Option_4 = {
    Text = "I can't wait!"
  },
  AvgCommunicate_100439_Content_1 = {
    Text = "I declare that emote images are the greatest art of the new era!"
  },
  AvgCommunicate_100439_Content_10 = {
    Text = "Since that's the case, could you please recommend the painters of these emote images for me?"
  },
  AvgCommunicate_100439_Content_11 = {Text = "Of course."},
  AvgCommunicate_100439_Content_2 = {
    Text = "Are you serious?"
  },
  AvgCommunicate_100439_Content_3 = {
    Text = "Of course! I have always been serious when it comes to art."
  },
  AvgCommunicate_100439_Content_7 = {Text = "..."},
  AvgCommunicate_100439_Content_8 = {
    Text = "Don't spam the chat. I agree with your thoughts."
  },
  AvgCommunicate_100439_Content_9 = {
    Text = "That's great! I knew you could understand the art in my eyes, truly the Keeper."
  },
  AvgCommunicate_100440_Content_1 = {
    Text = "Tonight the night is just right; it's time to carry out our secret operation!"
  },
  AvgCommunicate_100440_Content_10 = {
    Text = "Speak clearly, what is your plan? Be careful, I might tell Doresain."
  },
  AvgCommunicate_100440_Content_11 = {
    Text = "I just want to sneak into the kitchen and steal some ingredients, as for my artistic companion... No! I can't tell you who! I won't betray Sanga."
  },
  AvgCommunicate_100440_Content_12 = {Text = "Oh no."},
  AvgCommunicate_100440_Content_13 = {
    Text = "...Just like that. You admitted it all."
  },
  AvgCommunicate_100440_Content_14 = {
    Text = "Did you forget the consequences of being caught stealing kitchen ingredients as a model last time?"
  },
  AvgCommunicate_100440_Content_15 = {
    Text = "Last time was last time... This time I specifically chose the day of the Soulsfeast, and with Sanga helping me, it will definitely be fine."
  },
  AvgCommunicate_100440_Content_16 = {
    Text = "No! Don't tell Doresain, pleeeaaase?"
  },
  AvgCommunicate_100440_Content_17 = {
