    Text = "What are you talking about?"
  },
  AvgCommunicate_100440_Content_4 = {
    Text = "Didn't we agree? Doresain will definitely go to the ball first on the day of the Soulsfeast, and that will be our chance!"
  },
  AvgCommunicate_100440_Content_5 = {
    Text = "??? Did you send this to the wrong person?"
