  AvgCommunicate_100440_Content_6 = {
    Text = "Hey... wait..."
  },
  AvgCommunicate_100440_Content_7 = {
    Text = "Sorry, this was meant for my artistic companion; just pretend you didn't receive it."
  },
  AvgCommunicate_100440_Content_8 = {
    Text = "Artistic companion... it can't be..."
  },
  AvgCommunicate_100440_Content_9 = {
    Text = "Artistic companion... it can't be..."
  },
  AvgCommunicate_100440_Option_2 = {
    Text = "Secret operation?"
  },
  AvgCommunicate_100440_Option_3 = {
    Text = "What kind of new art is this?"
  },
  AvgCommunicate_100440_Option_8 = {
    Text = "Who is your artistic companion?"
  },
  AvgCommunicate_100440_Option_9 = {Text = "..."},
  AvgCommunicate_121371_Content_1 = {
    Text = "I saw her. So carefree, it's baffling."
  },
  AvgCommunicate_121371_Content_2 = {
    Text = "Her affection for mundane things is also incredibly naïve and absurd."
  },
  AvgCommunicate_121371_Content_3 = {
    Text = "...Murphy told me she couldn't get a single one of the new dolls and dresses she wanted to enter the lottery for this quarter."
  },
  AvgCommunicate_121371_Content_4 = {
    Text = "All the lucky draw numbers were bought out beforehand. Who could it have been? It's such a mystery."
  },
  AvgCommunicate_121371_Content_5 = {
    Text = "As the one who has endured for a significantly longer time, receiving a little compensation is only fair."
  },
  AvgCommunicate_121371_Content_6 = {
    Text = "...A compensation that lets you splurge on anything you want, perhaps because you came into a massive inheritance from the cult?"
  },
  AvgCommunicate_121371_Content_7 = {Text = "Heh."},
  AvgCommunicate_121371_Content_8 = {
    Text = "I'll concede that her past choices and luck might have been marginally better than mine."
  },
  AvgCommunicate_121371_Content_9 = {
    Text = "But she ought to realize that defying fate does not guarantee success every time."
  },
  AvgCommunicate_121372_Content_1 = {
    Text = "Outrageous! Disrespectful! Unforgivable!"
  },
  AvgCommunicate_121372_Content_10 = {
    Text = "You will..."
  },
  AvgCommunicate_121372_Content_11 = {
    Text = "So what will you do?"
  },
  AvgCommunicate_121372_Content_12 = {
    Text = "The students stopping to pet the cats are about to cause a phenomenal congestion in the school building with them. Truly an astonishing talent."
  },
  AvgCommunicate_121372_Content_13 = {
    Text = "I'm coming to rescue you right now."
  },
  AvgCommunicate_121372_Content_2 = {
    Text = "What's wrong?"
  },
  AvgCommunicate_121372_Content_3 = {
    Text = "This is utterly unreasonable! Why would Mythag allow creatures like this into the dorms!"
  },
  AvgCommunicate_121372_Content_4 = {
    Text = "Wait, I hear someone screaming in the dorm building. Was that you?"
  },
  AvgCommunicate_121372_Content_5 = {
    Text = "Why are there so many cats gathered at the door!?"
  },
  AvgCommunicate_121372_Content_6 = {
    Text = "These evil, treacherous little things have been following me since I appeared! It must be a conspiracy—they want to murder the Divine Mother!"
  },
  AvgCommunicate_121372_Content_7 = {
    Text = "...I don't think an evil creature intending to harm someone would be lying on its back, exposing its belly."
  },
  AvgCommunicate_121372_Content_8 = {
    Text = "The cats seem to have an unusually strong liking for you."
  },
  AvgCommunicate_121372_Content_9 = {
    Text = "Nonsense! As the Princess, I command you to get them out immediately, or I will... I will..."
  },
  AvgCommunicate_121372_Option_10 = {Text = "You will?"},
  AvgCommunicate_121372_Option_11 = {Text = "So?"},
  AvgCommunicate_121375_Content_1 = {
    Text = "I know what you're going to say. They volunteered."
  },
  AvgCommunicate_121375_Content_10 = {
    Text = "For the sake of your earnest devotion... I shall grant you this honor."
  },
  AvgCommunicate_121375_Content_11 = {
    Text = "Now, I want to see a box of fresh butter raspberry tarts."
  },
  AvgCommunicate_121375_Content_12 = {
    Text = "Fifteen minutes."
  },
  AvgCommunicate_121375_Content_13 = {
    Text = "This doesn't qualify as \"truly necessary,\" does it?!"
  },
  AvgCommunicate_121375_Content_14 = {Text = "Hmm?"},
  AvgCommunicate_121375_Content_15 = {
    Text = "...Fine, I understand. If I don't do it, you'll just have the fish-people do it."
  },
  AvgCommunicate_121375_Content_16 = {
    Text = "I'll buy one for you. Just stop making any more fishheads show up here."
  },
  AvgCommunicate_121375_Content_2 = {
    Text = "I don't know how you got in touch with them, but you absolutely cannot let those Seafarers appear at Mythag anymore to run your errands, hold your place in line, or do your homework!"
  },
  AvgCommunicate_121375_Content_3 = {
    Text = "Do you know how many teachers and students are complaining that their notebooks are becoming sticky?"
  },
  AvgCommunicate_121375_Content_4 = {
    Text = "They are merely ants who follow and insist on serving me."
  },
  AvgCommunicate_121375_Content_5 = {
    Text = "I detest that they took away my freedom, but as for enjoyment—I've never been one to object."
  },
  AvgCommunicate_121375_Content_6 = {
    Text = "So, why not make use of the waste?"
  },
  AvgCommunicate_121375_Content_7 = {
    Text = "Because I don't like the smell of fish."
  },
  AvgCommunicate_121375_Content_8 = {
    Text = "Because it's a safety hazard."
  },
  AvgCommunicate_121375_Content_9 = {
    Text = "If it is truly necessary, I will help you with your chores, homework excluded."
  },
  AvgCommunicate_121375_Option_7 = {
    Text = "Because I don't like the smell of fish."
  },
  AvgCommunicate_121375_Option_8 = {
    Text = "Because it's a safety hazard."
  },
  AvgCommunicate_122561_Content_1 = {
    Text = "%player%. It seemed like you were holding back just now. Is there something on your mind?"
  },
  AvgCommunicate_122561_Content_10 = {
    Text = "This feels bigger than that."
  },
  AvgCommunicate_122561_Content_11 = {
    Text = "Let me guess... it's related to that Mr. Fingal, right?"
  },
  AvgCommunicate_122561_Content_12 = {Text = "..."},
  AvgCommunicate_122561_Content_13 = {Text = "Yes."},
  AvgCommunicate_122561_Content_14 = {Text = "It's okay."},
  AvgCommunicate_122561_Content_15 = {
    Text = "I respect your choice."
  },
  AvgCommunicate_122561_Content_16 = {
    Text = "If you can't tell me for now, I won't press further."
  },
  AvgCommunicate_122561_Content_17 = {
    Text = "Sorry, %player%. once the situation clears up, I'll explain everything."
  },
  AvgCommunicate_122561_Content_18 = {
    Text = "Before that, let's focus on finding a way to return to our world."
  },
  AvgCommunicate_122561_Content_2 = {Text = "William..."},
  AvgCommunicate_122561_Content_3 = {
    Text = "Senior William..."
  },
  AvgCommunicate_122561_Content_4 = {
    Text = "You are still hiding things from me, right？"
  },
  AvgCommunicate_122561_Content_5 = {
    Text = "So you noticed."
  },
  AvgCommunicate_122561_Content_6 = {
