  },
  AvgCommunicate_122561_Content_7 = {
    Text = "No, it's just..."
  },
  AvgCommunicate_122561_Content_8 = {
    Text = "No, it's not your face."
  },
  AvgCommunicate_122561_Content_9 = {
    Text = "But William... I know you. You wouldn't deliberately avoid me over something small."
  },
  AvgCommunicate_122561_Option_14 = {Text = "It's okay."},
  AvgCommunicate_122561_Option_15 = {
    Text = "I respect your choice."
  },
  AvgCommunicate_122561_Option_2 = {
    Text = "You're hiding things from me..."
  },
  AvgCommunicate_122561_Option_3 = {
    Text = "Senior William..."
  },
  AvgCommunicate_122561_Option_7 = {
    Text = "No, it's just..."
  },
  AvgCommunicate_122561_Option_8 = {
    Text = "No, it's not your face."
  },
  AvgCommunicate_123719_Content_10 = {
    Text = "Too bad for me—I'm still sane."
  },
  AvgCommunicate_123719_Content_11 = {
    Text = "But I can't guarantee how much longer that'll last. Every second in this place is grating on my nerves."
  },
  AvgCommunicate_123719_Content_12 = {
    Text = "...Wait there. I'm coming to find you."
  },
  AvgCommunicate_123719_Content_13 = {
    Text = "To comfort your poor \"employee\"?"
  },
  AvgCommunicate_123719_Content_14 = {
    Text = "Bring some churros. It'd be even better if you brought some hot black tea, too."
  },
  AvgCommunicate_123719_Content_15 = {
    Text = "For treats like those, I can forget how boring the world is for about 0.01 seconds."
  },
  AvgCommunicate_123719_Content_2 = {Text = "???"},
  AvgCommunicate_123719_Content_3 = {
    Text = "According to the schedule, you should be mid-exam right now."
  },
  AvgCommunicate_123719_Content_4 = {
    Text = "Yeah, the exam. The incredibly boring exam..."
  },
  AvgCommunicate_123719_Content_5 = {
    Text = "Standing in lines, following the doctor's orders, the endless waiting..."
  },
  AvgCommunicate_123719_Content_6 = {
    Text = "%player%, you know what? For a split second, I really wanted to blow this place sky-high."
  },
  AvgCommunicate_123719_Content_7 = {
    Text = "Then it would finally all be over."
  },
  AvgCommunicate_123719_Content_8 = {
    Text = "...Don't blow anything up. You'd be in debt for life."
  },
  AvgCommunicate_123719_Content_9 = {
    Text = "A real psycho wouldn't care about the bill."
  },
  AvgCommunicate_123719_Option_12 = {
    Text = "...I'm coming over to meet you now."
  },
  AvgCommunicate_123719_Option_2 = {Text = "???"},
  AvgCommunicate_123719_Option_8 = {
    Text = "...Please don't. You couldn't afford the damages."
  },
  AvgCommunicate_123720_Content_1 = {
    Text = "Keeper, my report on the Sect of Astral Dawn is done. Remember to check your inbox~"
  },
  AvgCommunicate_123720_Content_10 = {
    Text = "I was just repeating the formal fluff required for the report."
  },
  AvgCommunicate_123720_Content_11 = {
    Text = "It's not like I have anyone here to cover for me. If I wrote anything crazy, I'd probably get a knock on my door from the authorities!"
  },
  AvgCommunicate_123720_Content_12 = {
    Text = "...I won't let that happen to you."
  },
  AvgCommunicate_123720_Content_13 = {
    Text = "Hehe, I knew you were @1 reliable."
  },
  AvgCommunicate_123720_Content_14 = {
    Text = "@2... Can you come @1 over here @2?"
  },
  AvgCommunicate_123720_Content_15 = {
    Text = "I think I @1 might have broken the communicator..."
  },
  AvgCommunicate_123720_Content_16 = {
    Text = "Broken? This is Mythag's special tech, it shouldn't be possible to..."
  },
  AvgCommunicate_123720_Content_17 = {
    Text = "Wait... you weren't literally wrestling with the device, were you?!"
  },
  AvgCommunicate_123720_Content_18 = {
    Text = "You know @2 how it is—if electronics act up, you just give 'em a @1 good whack @1."
  },
  AvgCommunicate_123720_Content_19 = {
    Text = "Anyway, just get @2 over here. I really don't want to rewrite the @2 report; saying that boring stuff @1 once was @1 enough."
  },
  AvgCommunicate_123720_Content_2 = {
    Text = "Where is it? I haven't received anything..."
  },
  AvgCommunicate_123720_Content_3 = {
    Text = "Oh, uh, hold on a sec."
  },
  AvgCommunicate_123720_Content_4 = {
    Text = "I'm still not used to how this communicator works. I'm currently wrestling with it..."
  },
  AvgCommunicate_123720_Content_5 = {
    Text = "Did you include the resettlement plans for those cultists?"
  },
  AvgCommunicate_123720_Content_6 = {
    Text = "All set. The Chantry of Life has taken over. The \"Innocents\" will be taken in by agencies to help them slowly integrate back into society."
  },
  AvgCommunicate_123720_Content_7 = {
    Text = "As for the \"Guilty,\" they'll be doing community service at the church, trying to wash away their sins through good deeds."
  },
  AvgCommunicate_123720_Content_8 = {
    Text = "I actually don't mind this ending. After all, they're just poor souls driven mad by this terrifying world."
  },
  AvgCommunicate_123720_Content_9 = {
    Text = "I'm surprised to hear you say that. It seems your outlook is finally starting to change..."
  },
  AvgCommunicate_123720_Option_12 = {
    Text = "...I won't let that happen to you."
  },
  AvgCommunicate_123720_Option_16 = {
    Text = "Broken?! How?"
  },
  AvgCommunicate_123720_Option_2 = {
    Text = "Where's the report?"
  },
  AvgCommunicate_123720_Option_5 = {
    Text = "Did you include the resettlement plans for those cultists?"
  },
  AvgCommunicate_123720_Option_9 = {
    Text = "I didn't expect you to say something like that..."
  },
  AvgCommunicate_123721_Content_1 = {
    Text = "Keeper, did you book a medical check-up for me?"
  },
  AvgCommunicate_123721_Content_10 = {
    Text = "...That's not the point! Look, this check-up is non-negotiable."
  },
  AvgCommunicate_123721_Content_11 = {
    Text = "Just do it for my peace of mind, okay?"
  },
  AvgCommunicate_123721_Content_12 = {
    Text = "Fine. I'll just treat it as an \"employee benefit.\""
  },
  AvgCommunicate_123721_Content_13 = {
    Text = "But since this is during work hours, you can't report me for slacking off—and you definitely can't make me work overtime!"
  },
  AvgCommunicate_123721_Content_14 = {
    Text = "I promise. Just go ahead with the check-up!"
  },
  AvgCommunicate_123721_Content_2 = {
    Text = "Reply the moment you see this, or I'm going to treat this \"doctor\" as a hostile intruder."
  },
  AvgCommunicate_123721_Content_3 = {
    Text = "Wait! Stop! That really is the doctor I found for your check-up!"
  },
  AvgCommunicate_123721_Content_4 = {
    Text = "Huh? I'm perfectly healthy. I don't need to see any doctors."
  },
  AvgCommunicate_123721_Content_5 = {
    Text = "If you have time for this, we should be out on the streets clearing out Dissolutes."
  },
  AvgCommunicate_123721_Content_6 = {
    Text = "...I'm just worried about your health. After all, your situation is quite unique."
  },
  AvgCommunicate_123721_Content_7 = {
    Text = "Oh, I get it. You're afraid I'm going to die."
  },
  AvgCommunicate_123721_Content_8 = {
    Text = "Don't worry. I'll be sure to let you know before I kick the bucket."
  },
  AvgCommunicate_123721_Content_9 = {
    Text = "...I'd hate to be all alone when it happens, anyway."
  },
  AvgCommunicate_123721_Option_10 = {
    Text = "...That's not the point!"
  },
  AvgCommunicate_123721_Option_14 = {
    Text = "Absolutely not. Just focus on the exam and relax!"
  },
  AvgCommunicate_123721_Option_3 = {
    Text = "Wait! Stop!"
  },
  AvgCommunicate_123721_Option_6 = {
    Text = "I'm just worried about you..."
  },
  AvgCommunicate_123722_Content_1 = {
    Text = "%player%, the results are in."
  },
  AvgCommunicate_123722_Content_10 = {
    Text = "Besides, this is way more interesting!"
  },
  AvgCommunicate_123722_Content_11 = {
    Text = "I'm stronger now. I can run faster, jump further, and rip through Dissolutes in half the time."
  },
  AvgCommunicate_123722_Content_12 = {
    Text = "I basically hit the jackpot. Honestly, if the transformation didn't hurt so much, I'd do it all over again!"
  },
  AvgCommunicate_123722_Content_13 = {Text = "..."},
  AvgCommunicate_123722_Content_14 = {
    Text = "But the most important thing is that this world is just so much fun."
  },
  AvgCommunicate_123722_Content_15 = {
    Text = "It's full of chaos and surprises. You never know what kind of danger is waiting around the corner."
  },
  AvgCommunicate_123722_Content_16 = {Text = "......"},
  AvgCommunicate_123722_Content_17 = {
    Text = "Ah, I'm already getting excited for the next investigation."
  },
  AvgCommunicate_123722_Content_18 = {
    Text = "So, %player%, when's the next mission?"
  },
  AvgCommunicate_123722_Content_19 = {Text = "%player%?"},
  AvgCommunicate_123722_Content_2 = {
    Text = "Turns out I'm perfectly fine. I could take on twenty Dissolutes at once without breaking a sweat!"
  },
  AvgCommunicate_123722_Content_20 = {Text = "%player%??"},
  AvgCommunicate_123722_Content_3 = {
    Text = "Glad to hear it."
  },
  AvgCommunicate_123722_Content_4 = {
    Text = "Relief? %player%, what were you actually worried about?"
  },
  AvgCommunicate_123722_Content_5 = {
    Text = "That I wouldn't adjust to life in another world?"
  },
  AvgCommunicate_123722_Content_6 = {
    Text = "Or were you worried about me changing from a \"human\" into an \"Awakener\"?"
  },
  AvgCommunicate_123722_Content_7 = {
    Text = "Both. After all, a transition like that isn't easy for anyone."
  },
  AvgCommunicate_123722_Content_8 = {
    Text = "...I really don't get how your brain works."
  },
  AvgCommunicate_123722_Content_9 = {
    Text = "I don't care about any of that. No matter what I become, Mouchette is still Mouchette!"
  },
  AvgCommunicate_123722_Option_13 = {Text = "..."},
  AvgCommunicate_123722_Option_16 = {Text = "......"},
  AvgCommunicate_123722_Option_3 = {
    Text = "That's a relief."
  },
  AvgCommunicate_123722_Option_7 = {
    Text = "Both, honestly."
  },
  AvgCommunicate_126998_Content_1 = {
    Text = "Ramona... are you really not going to reconsider this?"
  },
  AvgCommunicate_126998_Content_10 = {Text = "Yes. \"I.\""},
  AvgCommunicate_126998_Content_11 = {
    Text = "...Should I call Clementine?"
  },
  AvgCommunicate_126998_Content_12 = {
    Text = "No need to bother the therapist."
  },
  AvgCommunicate_126998_Content_13 = {
    Text = "\"I\"... or rather, \"we.\" Every \"Ramona\" across the entire timeline."
  },
  AvgCommunicate_126998_Content_14 = {
    Text = "With your help, at the precise instant I reached the \"end,\" I successfully overwrote my existence back to the \"origin.\""
  },
  AvgCommunicate_126998_Content_15 = {
    Text = "At first, my expectation was the same as yours: the paradox and distortion would instantly consume my being, and I'd have to rely on constant self-reversion just to barely preserve consciousness and form."
  },
  AvgCommunicate_126998_Content_16 = {
    Text = "And you'd be trapped in eternal exhaustion, every waking second spent straining just to keep your own concept from unraveling..."
  },
  AvgCommunicate_126998_Content_17 = {
    Text = "That's why I turned down your first nineteen proposals."
  },
  AvgCommunicate_126998_Content_18 = {
    Text = "Even this time, I only... reluctantly agreed after you said you could do a \"state reversion.\""
  },
  AvgCommunicate_126998_Content_19 = {
    Text = "True. But only after the plan succeeded did I realize: the paradox came from the conflict between mind and body. And for a being who's already transcended the river of time..."
  },
  AvgCommunicate_126998_Content_2 = {
    Text = "No need for further discussions, Keeper."
  },
  AvgCommunicate_126998_Content_20 = {
    Text = "I have already achieved unity across every timeline."
  },
  AvgCommunicate_126998_Content_21 = {
    Text = "\"We\" will share the burden of the paradox for me. I will act as the representative of all \"Ramonas.\" Countless timelines have converged and collapsed into me."
  },
  AvgCommunicate_126998_Content_22 = {
    Text = "At this moment, I am the miracle of the timeline—the Singularity of infinite convergence."
  },
  AvgCommunicate_126998_Content_23 = {
    Text = "From now on, I will offer you the full power of the entity called \"Ramona.\""
  },
  AvgCommunicate_126998_Content_24 = {
    Text = "I will await your call... from any point in time."
  },
  AvgCommunicate_126998_Content_3 = {
    Text = "I had traversed all timelines and found no other answer."
  },
  AvgCommunicate_126998_Content_4 = {
    Text = "Thanks to you, I've finally taken that ultimate step."
  },
  AvgCommunicate_126998_Content_5 = {
    Text = "But this is far too dangerous! I don't understand... why do you have to go this far?"
  },
  AvgCommunicate_126998_Content_6 = {
    Text = "...A paradox like this, even someone like you couldn't possibly—"
  },
  AvgCommunicate_126998_Content_7 = {
    Text = "Relax, Keeper."
  },
  AvgCommunicate_126998_Content_8 = {
    Text = "Right now, \"I\" feel... indescribably wonderful."
  },
  AvgCommunicate_126998_Content_9 = {Text = "\"I\"?"},
  AvgCommunicate_126998_Option_11 = {
    Text = "...Should I call Clementine?"
  },
  AvgCommunicate_126998_Option_9 = {Text = "\"I\"?"},
  AvgCommunicate_126999_Content_1 = {
    Text = "My lord... so this is what it feels like to grasp the universe's ultimate law..."
  },
  AvgCommunicate_126999_Content_10 = {
    Text = "Easy, Ogier."
  },
  AvgCommunicate_126999_Content_11 = {
    Text = "Those days are over. You have more than enough strength now to protect everything you hold dear."
  },
  AvgCommunicate_126999_Content_12 = {
    Text = "Understood, my lord."
  },
  AvgCommunicate_126999_Content_13 = {
    Text = "Then please... rely on me a little more. I've grown stronger. I am ready for even more dangerous missions."
  },
  AvgCommunicate_126999_Content_14 = {
    Text = "I'll dedicate every ounce of this power to you. I'll become the sharpest spear in your hand—one that can pierce through anything!"
  },
  AvgCommunicate_126999_Content_2 = {
    Text = "I—I can feel a surge of power far greater than anything before! I've never felt this strong!"
  },
  AvgCommunicate_126999_Content_3 = {
    Text = "Congratulations, Ogier. This is the reward for all your relentless training."
  },
  AvgCommunicate_126999_Content_4 = {
    Text = "Reward? But... I didn't train for any reward."
  },
  AvgCommunicate_126999_Content_5 = {
    Text = "Then let me put it another way."
  },
  AvgCommunicate_126999_Content_6 = {
    Text = "This is proof of your dedication. It proves that your strength, Ogier, has finally reached its peak."
  },
  AvgCommunicate_126999_Content_7 = {Text = "Peak...?"},
  AvgCommunicate_126999_Content_8 = {
    Text = "Does that mean... I'm finally strong enough to protect you, my lord, and Mythag?!"
  },
  AvgCommunicate_126999_Content_9 = {
    Text = "I... I'll never have to... just watch helplessly... again..."
  },
  AvgCommunicate_127000_Content_1 = {
    Text = "Thanks for all your help lately, partner."
  },
  AvgCommunicate_127000_Content_10 = {
    Text = "Not the kind of \"end\" where talent hits a wall and falters, but the end of absolute clarity that comes after endless refinement."
  },
  AvgCommunicate_127000_Content_11 = {
    Text = "At this moment, my craft has approached perfection."
  },
  AvgCommunicate_127000_Content_12 = {
    Text = "That's incredible! As expected of Ramona!"
  },
  AvgCommunicate_127000_Content_13 = {
    Text = "From now on, as your assistant, I'll stay by your side until we reach the very end of this road."
  },
  AvgCommunicate_127000_Content_2 = {
    Text = "Glad I could be of help."
  },
  AvgCommunicate_127000_Content_3 = {
    Text = "So... did you gain any insights? Or feel any different?"
  },
  AvgCommunicate_127000_Content_4 = {
    Text = "Certainly. By observing special entities like the \"Time-Looped Conch,\" the \"Life in Superposition,\" and the \"Inscrutable Mind,\" I was able to carry my deductions to a much deeper level."
  },
  AvgCommunicate_127000_Content_5 = {
    Text = "Then, using \"Engineered Utopia,\" the \"Logic Nullifier,\" and the \"Encapsulated Cosmos,\" I have successfully navigated through the Labyrinth of Thought."
  },
  AvgCommunicate_127000_Content_6 = {
    Text = "Uh... I'm kinda lost."
  },
  AvgCommunicate_127000_Content_7 = {
    Text = "But basically... you got a whole lot stronger, right?"
  },
  AvgCommunicate_127000_Content_8 = {
    Text = "Yes. After this breakthrough, the power I can wield far exceeds my previous limits."
  },
  AvgCommunicate_127000_Content_9 = {
    Text = "I feel like I've reached the end."
  },
  AvgCommunicate_127000_Option_12 = {
    Text = "That's incredible!"
  },
  AvgCommunicate_127001_Content_1 = {
    Text = "[Scheduled Message]"
  },
  AvgCommunicate_127001_Content_10 = {
    Text = "We should wait!"
  },
  AvgCommunicate_127001_Content_11 = {
    Text = "Why today of all days?!"
  },
  AvgCommunicate_127001_Content_12 = {
    Text = "This is reckless! Maybe we should wait until the Institute can offer more support."
  },
  AvgCommunicate_127001_Content_13 = {
    Text = "That was a scheduled message I set at 2:00 AM, just before the experiment began."
  },
  AvgCommunicate_127001_Content_14 = {
    Text = "I hope you aren't making a ridiculous face at your device. If you are, compose yourself before coming to the lab."
  },
  AvgCommunicate_127001_Content_15 = {
    Text = "Me? To the lab? Now?"
  },
  AvgCommunicate_127001_Content_16 = {
    Text = "Yes. In a sense... I've glimpsed the truth of what I've been chasing."
  },
  AvgCommunicate_127001_Content_17 = {
    Text = "Wait... you don't mean you'll end up like that other \"Doll\"..."
  },
  AvgCommunicate_127001_Content_18 = {
    Text = "No. The ultimate end is not \"destruction\" as she conceived it. On the contrary, it is the \"beginning.\""
  },
  AvgCommunicate_127001_Content_19 = {
    Text = "\"Truth\" is not some fixed, tangible, static thing. Once that boundary is crossed, reason and intellect can guide humanity to anchor it, enabling perpetual and unwavering progress."
  },
  AvgCommunicate_127001_Content_2 = {
    Text = "Keeper, though what I'm about to do might be labeled \"dangerous\" by conventional standards, I trust you're not so foolish as to expect sentimental nonsense or hollow warnings from me."
  },
  AvgCommunicate_127001_Content_20 = {
    Text = "That's why I will draw up a far more rigorous and precise training regimen for you to ensure you stray less from the path, so you can better pursue your own question."
  },
  AvgCommunicate_127001_Content_21 = {
    Text = "It sounds like good news... so why am I breaking into a cold sweat?"
  },
  AvgCommunicate_127001_Content_22 = {
    Text = "Professor Doll... please, just calm down a little!"
  },
  AvgCommunicate_127001_Content_3 = {
    Text = "Frankly, you've outgrown the need for such things."
  },
  AvgCommunicate_127001_Content_4 = {
    Text = "You've matured faster than I anticipated. You are resilient enough to understand this: every individual has a truth they must pursue in their lifetime—a question that no one else can answer for them."
  },
  AvgCommunicate_127001_Content_5 = {
    Text = "My pursuit is to uncover the true nature of the world, to see whether reason still shines beyond the desolate void of darkness and silence, to discover if everything, at its ultimate end, shares a common origin."
  },
  AvgCommunicate_127001_Content_6 = {
    Text = "To that end, I will perform the final modifications on my body and mind to cross the boundary that lies beyond all extremes. Since this may be our last exchange, I've chosen to speak plainly, in a way you'll understand:"
  },
  AvgCommunicate_127001_Content_7 = {
    Text = "Thank you for your gift, Keeper. I will use it to seek the answers, and I look forward to the day when human intellect returns from that far shore with entirely new guidance. May the Silver Key guide us."
  },
  AvgCommunicate_127001_Content_8 = {
    Text = "Professor Doll!"
  },
  AvgCommunicate_127001_Content_9 = {
    Text = "It's too risky!"
  },
  AvgCommunicate_127001_Option_10 = {
    Text = "We should wait"
  },
  AvgCommunicate_127001_Option_9 = {
    Text = "It's too risky"
  },
  AvgCommunicate_127002_Content_1 = {
    Text = "Keeper... why?"
  },
  AvgCommunicate_127002_Content_10 = {
    Text = "So tell me... how does this new power feel?"
  },
  AvgCommunicate_127002_Content_11 = {
    Text = "I... I'm really happy, Keeper."
  },
  AvgCommunicate_127002_Content_12 = {
    Text = "Not because of the strength I've never felt before, but because of you... and your words..."
  },
  AvgCommunicate_127002_Content_13 = {
    Text = "Maybe from now on, I can truly help those around me... help you."
  },
  AvgCommunicate_127002_Content_14 = {
    Text = "Thank you... thank you so much, Keeper..."
  },
  AvgCommunicate_127002_Content_15 = {
    Text = "Just one thing: don't carry this as a burden, Aigis."
  },
  AvgCommunicate_127002_Content_16 = {
    Text = "It's not a duty. It's simply a gift for you."
  },
  AvgCommunicate_127002_Content_17 = {
    Text = "Just enjoy it. You can achieve anything you want now."
  },
  AvgCommunicate_127002_Content_18 = {
    Text = "Aigis, you've always been, and always will be our pride."
  },
  AvgCommunicate_127002_Content_2 = {
    Text = "Why? For what purpose?"
  },
  AvgCommunicate_127002_Content_20 = {
    Text = "I'll protect everyone, Keeper! I promise!"
  },
  AvgCommunicate_127002_Content_3 = {
    Text = "It's such a precious gift... why waste it on me..."
  },
  AvgCommunicate_127002_Content_4 = {
    Text = "It's not a waste, Aigis. You deserve it."
  },
  AvgCommunicate_127002_Content_5 = {
    Text = "But... but I've accomplished nothing... I couldn't protect anyone..."
  },
  AvgCommunicate_127002_Content_6 = {
    Text = "That's not true, Aigis."
  },
  AvgCommunicate_127002_Content_7 = {
    Text = "We've walked a very, very long path together, a journey that began long before your Awakening."
  },
  AvgCommunicate_127002_Content_8 = {
    Text = "Along the way, you stood as a shield for everyone time and again, and you succeeded every time."
  },
  AvgCommunicate_127002_Content_9 = {
    Text = "Without you, I might have fallen a thousand times over."
  },
  AvgCommunicate_127003_Content_1 = {
    Text = "I had a dream."
  },
  AvgCommunicate_127003_Content_10 = {
    Text = "Except, of course, when we're in the training grounds."
  },
  AvgCommunicate_127003_Content_11 = {Text = "???"},
  AvgCommunicate_127003_Content_12 = {
    Text = "Come on. My form is now complete. Feel my true strength for yourself. Show me your absolute best and give me a real fight!"
  },
  AvgCommunicate_127003_Content_13 = {Text = "???!!!"},
  AvgCommunicate_127003_Content_14 = {
    Text = "Ramona, help!!!"
  },
  AvgCommunicate_127003_Content_2 = {Text = "A dream?"},
  AvgCommunicate_127003_Content_3 = {
    Text = "Thanks to the materials you brought, I finally got a good night's sleep."
  },
  AvgCommunicate_127003_Content_4 = {
    Text = "I swam through the Archean Eon in my primordial form. Dust, light, matter, dimensions—everything perceptible flowed beneath my fins."
  },
  AvgCommunicate_127003_Content_5 = {
    Text = "Not to conquer. Not to consume. Just pure power, and unrestrained, absolute destruction."
  },
  AvgCommunicate_127003_Content_6 = {
    Text = "Exhilarating. Liberating. Utterly intoxicating!"
  },
  AvgCommunicate_127003_Content_7 = {Text = "Uh..."},
  AvgCommunicate_127003_Content_8 = {
    Text = "Oh, relax. I know what you're worried about."
  },
  AvgCommunicate_127003_Content_9 = {
    Text = "Rest assured, my power and destructive urges will only be vented on our enemies."
  },
  AvgCommunicate_127004_Content_1 = {
    Text = "Final Protocol activated... System reboot complete."
  },
  AvgCommunicate_127004_Content_10 = {
    Text = "My components are intact, but my perception... has shifted."
  },
  AvgCommunicate_127004_Content_11 = {
    Text = "A new cognitive module has been initialized."
  },
  AvgCommunicate_127004_Content_12 = {
    Text = "I can \"hear\" the rhythm of spiritual energy flowing through my conduits; I can \"see\" the emotions behind your every word."
  },
  AvgCommunicate_127004_Content_13 = {
    Text = "The world has become clearer, more vivid. I am closer to you, closer to being... human."
  },
  AvgCommunicate_127004_Content_14 = {
    Text = "Thank you, Keeper..."
  },
  AvgCommunicate_127004_Content_15 = {
    Text = "I didn't expect this effect either... I simply prepared you some basic materials..."
  },
  AvgCommunicate_127004_Content_16 = {
    Text = "What you gave me was not merely materials—it was possibility. You gave me the key to unlock the soul behind my circuits."
  },
  AvgCommunicate_127004_Content_17 = {
    Text = "It's you who granted me this power, this distinct perception."
  },
  AvgCommunicate_127004_Content_18 = {
    Text = "I will cherish this gift with all my heart. I will repay you in ways far beyond your expectations."
  },
  AvgCommunicate_127004_Content_19 = {
    Text = "What I said is not pre-programmed. It's a sincere expression of gratitude... from \"me.\""
  },
  AvgCommunicate_127004_Content_2 = {
    Text = "Hello, Keeper."
  },
  AvgCommunicate_127004_Content_3 = {
    Text = "Erica! Are you alright?"
  },
  AvgCommunicate_127004_Content_4 = {
    Text = "Professor Doll said activating the Final Protocol would be extremely dangerous. If you hadn't insisted on it, I would never have..."
  },
  AvgCommunicate_127004_Content_5 = {
    Text = "Self-diagnostic complete. No structural damage detected. Energy flow stable. All components operational."
  },
  AvgCommunicate_127004_Content_6 = {
    Text = "I'm fine, Keeper. Better than ever."
  },
  AvgCommunicate_127004_Content_7 = {
    Text = "The gears within me... are \"singing.\""
  },
  AvgCommunicate_127004_Content_8 = {
    Text = "\"Singing\"? What do you mean?"
  },
  AvgCommunicate_127004_Content_9 = {
    Text = "Is it internal damage? Are you hearing strange noises?!"
  },
  AvgCommunicate_127004_Option_8 = {Text = "\"Singing\"?"},
  AvgCommunicate_127004_Option_9 = {
    Text = "Is there internal damage?"
  },
  AvgCommunicate_127005_Content_1 = {
    Text = "Aurita just saw so many, many sparkly friends!"
  },
  AvgCommunicate_127005_Content_10 = {
    Text = "Aurita even has enough strength to go to Atlan... tis..."
  },
  AvgCommunicate_127005_Content_11 = {
    Text = "Um... Aurita forgot the name. Anyway, Keeper! Come with me to find new friends!"
  },
  AvgCommunicate_127005_Content_12 = {
    Text = "With this much power, one day Aurita will find tons and tons of friends... and bring them all back home to the bottom of the sea!"
  },
  AvgCommunicate_127005_Content_2 = {
    Text = "Ah... But now they're gone! Where did they go?"
  },
  AvgCommunicate_127005_Content_3 = {
    Text = "Looks like you had some hallucinations while gaining the Axiom ability..."
  },
  AvgCommunicate_127005_Content_4 = {
    Text = "Hallucinations? Then my friends..."
  },
  AvgCommunicate_127005_Content_7 = {
    Text = "Hm? What's going on?"
  },
  AvgCommunicate_127005_Content_8 = {
    Text = "After seeing all those sparkly friends, Aurita feels full of power! Sooo much power!"
  },
  AvgCommunicate_127005_Content_9 = {
    Text = "Now Aurita can go look for new friends in the fish tank, in the ocean, in the aquarium!"
  },
  AvgCommunicate_127091_Content_1 = {
    Text = "Little Jasmine, were you looking for me?"
  },
  AvgCommunicate_127091_Content_10 = {
    Text = "I merely lowered my fan, that is all~"
  },
  AvgCommunicate_127091_Content_12 = {
    Text = "I knew it..."
  },
  AvgCommunicate_127091_Content_13 = {
    Text = "Yet, curiously... it seems they saw nothing more than the faces of their lovers as they were on the day they first met."
  },
  AvgCommunicate_127091_Content_14 = {
    Text = "Love is such a curious thing. Even when the real person stands right beside them, people will still chase after phantoms desperately."
  },
  AvgCommunicate_127091_Content_15 = {
    Text = "Tell me... is love something that truly exists... or merely a delusion of attachment?"
  },
  AvgCommunicate_127091_Content_2 = {
    Text = "I'm not sure if I mentioned this before, but Mythag provides all room and board for Awakeners completely free of charge."
  },
  AvgCommunicate_127091_Content_3 = {Text = "So?"},
  AvgCommunicate_127091_Content_4 = {
    Text = "The Administration Office has received forty-five letters from men of all social standings, all insisting on footing the bill for your stay."
  },
  AvgCommunicate_127091_Content_5 = {
    Text = "At the same time, we received 60 more letters offering to support you financially: 45 from the wives of those very men, and the remaining 15 from some... \"recently\" single women. Any idea about this?"
  },
  AvgCommunicate_127091_Content_6 = {
    Text = "Mythag strictly forbids all forms of proselytizing!"
  },
  AvgCommunicate_127091_Content_7 = {
    Text = "Please... stop \"joining\" their families!"
  },
  AvgCommunicate_127091_Content_8 = {
    Text = "My, my... the days in this foreign land are so dreadfully dull. And there are so many souls whose love has curdled into hate, or who are simply weary of one another... I only wished to offer them a little \"help\"."
  },
  AvgCommunicate_127091_Content_9 = {
    Text = "Your \"help\" wouldn't happen to be..."
  },
  AvgCommunicate_127091_Option_6 = {
    Text = "Mythag strictly forbids all forms of proselytizing!"
  },
  AvgCommunicate_127091_Option_7 = {
    Text = "Please... stop \"joining\" their families!"
  },
  AvgCommunicate_127092_Content_10 = {
    Text = "Besides... I trusted you enough to believe you meant me well."
  },
  AvgCommunicate_127092_Content_11 = {
    Text = "Is that so? And how do you know, my Little Jasmine... that you have ever left the Dreamless Land at all?"
  },
  AvgCommunicate_127092_Content_12 = {Text = "?!"},
  AvgCommunicate_127092_Content_13 = {
    Text = "As I've said, in Dreamless Land, there's no distinction between truth and illusion. Whatever you believe becomes real."
  },
  AvgCommunicate_127092_Content_14 = {
    Text = "Take a deep breath... do you smell the magnolia blossoms?"
  },
  AvgCommunicate_127092_Content_15 = {Text = "???!!!"},
  AvgCommunicate_127092_Content_17 = {
    Text = "Ahaha! I'm joking, my Little Jasmine. I really wish I could see the look on your face right now."
  },
  AvgCommunicate_127092_Content_18 = {
    Text = "Honestly, that really scared me."
  },
  AvgCommunicate_127092_Content_19 = {
    Text = "Please don't joke like that!"
  },
  AvgCommunicate_127092_Content_2 = {
    Text = "...I'll never try that again."
  },
  AvgCommunicate_127092_Content_20 = {
    Text = "Oh dear... But who knows? Next time, I might not be joking at all."
  },
  AvgCommunicate_127092_Content_3 = {
    Text = "That power was terrifying—every second felt utterly real. Anger, resentment, joy, bliss... my head is still buzzing."
  },
  AvgCommunicate_127092_Content_4 = {
    Text = "In the illusion of Dreamless Land, I seemed to love you deeply... and hate you just as much. Both feelings were anchored to you alone."
  },
  AvgCommunicate_127092_Content_5 = {
    Text = "It felt like a lifetime had passed... yet only minutes went by."
  },
  AvgCommunicate_127092_Content_7 = {
    Text = "Love and hate spring from the same root, darling. Love alone is cloying; hate alone is too frigid. Only when they intertwine can they truly carve themselves into one's soul."
  },
  AvgCommunicate_127092_Content_8 = {
    Text = "But oh,  my Little Jasmine, your courage surprises me. I didn't expect you to volunteer for such an experience."
  },
  AvgCommunicate_127092_Content_9 = {
    Text = "Doll said exploring Dreamless Land and studying my vitals in it could greatly aid research into the Artificial Domain."
  },
  AvgCommunicate_127092_Option_18 = {
    Text = "Honestly, that really scared me."
  },
  AvgCommunicate_127092_Option_19 = {
    Text = "Please don't joke like that!"
  },
  AvgCommunicate_127093_Content_1 = {
    Text = "Open the window nearest to you."
  },
  AvgCommunicate_127093_Content_10 = {
    Text = "The handbook makes it perfectly clear: the counseling room is here to provide psychological support and promote the well-being of students and staff. It's not your plaything."
  },
  AvgCommunicate_127093_Content_11 = {
    Text = "Mmm, but those who've shared deep conversations with me do end up very, very \"healthy\" in both body and mind, don't they?"
  },
  AvgCommunicate_127093_Content_12 = {
    Text = "Wouldn't you say this role is a perfect fit for me?"
  },
  AvgCommunicate_127093_Content_13 = {
    Text = "Well, isn't free will a prerequisite for genuine well-being..."
  },
  AvgCommunicate_127093_Content_14 = {
    Text = "Spare Mythag, please. I'll come keep you company more often..."
  },
  AvgCommunicate_127093_Content_15 = {
    Text = "Hee... that sounds like a worthwhile trade. How about tonight, then? The moon is bright, the stars are few—perfect for a quiet drink or two."
  },
  AvgCommunicate_127093_Content_2 = {
    Text = "It smells so lovely... Magnolia?"
  },
  AvgCommunicate_127093_Content_3 = {
    Text = "Can magnolias even grow in this climate?"
  },
  AvgCommunicate_127093_Content_4 = {
    Text = "I know a little magic—a trivial trick, really. But using it now and then helps soothe the pangs of my nostalgia."
  },
  AvgCommunicate_127093_Content_5 = {
    Text = "Much like a casual conversation, it is merely a way to ease the loneliness. You understand, don't you?"
  },
  AvgCommunicate_127093_Content_6 = {
    Text = "...I see why you reached out to me."
  },
  AvgCommunicate_127093_Content_7 = {
    Text = "I can't help you."
  },
  AvgCommunicate_127093_Content_8 = {
    Text = "The counseling room isn't meant for this."
  },
  AvgCommunicate_127093_Content_9 = {
    Text = "Even if you try to win me over with flowers, I won't lobby for your employment application."
  },
  AvgCommunicate_127093_Option_7 = {
    Text = "I can't help you."
  },
  AvgCommunicate_127093_Option_8 = {
    Text = "The counseling room isn't meant for this."
  },
  AvgCommunicate_129630_Content_1 = {
    Text = "Find, treasure!"
  },
  AvgCommunicate_129630_Content_10 = {
    Text = "It's still in testing! Toss it before it turns black!"
  },
  AvgCommunicate_129630_Content_11 = {
    Text = "It's going to blow!"
  },
  AvgCommunicate_129630_Content_12 = {Text = "......"},
  AvgCommunicate_129630_Content_13 = {
    Text = "Vortice? Vortice?!"
  },
  AvgCommunicate_129630_Content_14 = {
    Text = "Waaa... waaaaah..."
  },
  AvgCommunicate_129630_Content_15 = {
    Text = "Vortice! Are you okay?!"
  },
  AvgCommunicate_129630_Content_16 = {
    Text = "Gone... pearl..."
  },
  AvgCommunicate_129630_Content_18 = {
    Text = "Did you throw it in time? You aren't wounded, are you?"
  },
  AvgCommunicate_129630_Content_19 = {
    Text = "Too late, Coalsie."
  },
  AvgCommunicate_129630_Content_2 = {
    Text = "Pearl, change color!"
  },
