  AvgCommunicate_57957_Content_3 = {
    Text = "Like all art, sculpting is also a very personal thing."
  },
  AvgCommunicate_57957_Content_4 = {
    Text = "Not everyone can see these stone creations as an extension of themselves; a continuation of their life like I do."
  },
  AvgCommunicate_57957_Content_5 = {
    Text = "But you're different, aren't you?"
  },
  AvgCommunicate_57957_Content_6 = {
    Text = "My dear \"Ms. Coral\"?"
  },
  AvgCommunicate_57957_Option_2 = {
    Text = "I should have guessed."
  },
  AvgCommunicate_57958_Content_1 = {
    Text = "Excuse me, {Male=sir,Female=miss}, may I have a moment of your time?"
  },
  AvgCommunicate_57958_Content_10 = {
    Text = "It doesn't matter. If it's to spread my Lord's grace, I won't give up even on the most stubborn of people."
  },
  AvgCommunicate_57958_Content_11 = {
    Text = "Tomorrow at 3 AM, I will hold a ceremony in Mythag Hall to narrate the great deeds of my master."
  },
  AvgCommunicate_57958_Content_12 = {
    Text = "As someone who is deeply linked with my Lord, I hope Keeper %sirormadam% attends on time."
  },
  AvgCommunicate_57958_Content_2 = {
    Text = "I would like to talk to you about our young king and savior—Tulu."
  },
  AvgCommunicate_57958_Content_3 = {
    Text = "Chief Priest, please be mindful of your status. Please don't imitate charlatans..."
  },
  AvgCommunicate_57958_Content_4 = {
    Text = "Juliette suggested that in order to increase number of followers, we need to adopt a gentler and more proactive approach to our preaching."
  },
  AvgCommunicate_57958_Content_5 = {
    Text = "I think there is merit in that suggestion."
  },
  AvgCommunicate_57958_Content_6 = {
    Text = "As long as it can spread the grace of our Lord, I'm willing to imitate any modern methods."
  },
  AvgCommunicate_57958_Content_7 = {
    Text = "I forgot to tell you... I actually prefer Hass..."
  },
  AvgCommunicate_57958_Content_9 = {
    Text = "Blasphemy... Foolishness..."
  },
  AvgCommunicate_57958_Option_3 = {
    Text = "Please don't imitate charlatans..."
