  AvgCommunicate_57999_Content_3 = {
    Text = "Aigis made candies she wanted to share at the afternoon tea party..."
  },
  AvgCommunicate_57999_Content_4 = {
    Text = "If the Keeper is busy, I can secretly set some aside for you..."
  },
  AvgCommunicate_57999_Content_5 = {
    Text = "Thank you, little Aigis. I'd love that."
  },
  AvgCommunicate_57999_Content_6 = {
    Text = "Hey, you! How dare you brush aside Aigis's invitation like that!"
  },
  AvgCommunicate_57999_Content_7 = {Text = "?"},
  AvgCommunicate_57999_Content_8 = {
    Text = "Listen up! If I don't see you at the tea party this afternoon, I'll have Brown steal all your candy!"
