  AvgCommunicate_60943_Content_1 = {
    Text = "Partner, we're short-handed. I need to prepare at the site early alone and won't be able to join you this time."
  },
  AvgCommunicate_60943_Content_10 = {
    Text = "I know. You always take everyone into consideration."
