  AvgCommunicate_60943_Content_12 = {Text = "..."},
  AvgCommunicate_60943_Content_13 = {
    Text = "You're right."
  },
  AvgCommunicate_60943_Content_14 = {
    Text = "This time, I'll be counting on your support, partner."
  },
  AvgCommunicate_60943_Content_2 = {
    Text = "I have prepared several contingency plans for you. In case of emergencies, you can refer to the corresponding directory."
  },
  AvgCommunicate_60943_Content_3 = {
    Text = "Additionally, I've requested an extra emergency Gnosis for you. Even though manpower is tight, I'll try to arrange for someone else to accompany you."
