  AvgCommunicate_60943_Content_4 = {Text = "Ramona."},
  AvgCommunicate_60943_Content_5 = {
    Text = "I know you're worried about me. Thank you for everything you've done."
  },
  AvgCommunicate_60943_Content_6 = {
    Text = "But I'm no longer the weak and naive freshman. I can handle this."
  },
  AvgCommunicate_60943_Content_7 = {
    Text = "Of course, I trust your abilities, it's just..."
  },
  AvgCommunicate_60943_Content_8 = {
    Text = "Sorry, I'm used to simulating everything. If I'm not around, I can't help but imagine the worst possibilities."
  },
  AvgCommunicate_60943_Content_9 = {
    Text = "I can't accept that I couldn't prevent the worst outcome..."
  },
  AvgCommunicate_60943_Option_10 = {
    Text = "I know. You always take everyone into consideration."
  },
  AvgCommunicate_60943_Option_4 = {Text = "Ramona."},
  AvgCommunicate_66973_Content_1 = {
    Text = "Keeper, thank you for suggesting that my sister and I attend the party together."
