  },
  AvgCommunicate_66973_Content_11 = {
    Text = "Mm, the bond between you sisters is truly deep..."
  },
  AvgCommunicate_66973_Content_12 = {
    Text = "Of course, my sister will always be the most important person to me, and I'll continue to take care of her."
  },
  AvgCommunicate_66973_Content_13 = {
    Text = "Looks like it's my turn to guide my sister at the next gathering."
