  AvgCommunicate_66973_Content_15 = {
    Text = "No problem!"
  },
  AvgCommunicate_66973_Content_2 = {
    Text = "You're welcome! Happy to be of service!"
  },
  AvgCommunicate_66973_Content_3 = {
    Text = "I always depended on my sister. She always appeared strong in front of me, even a bit tough."
  },
  AvgCommunicate_66973_Content_4 = {
    Text = "I never expected that, in this situation, even my sister would be flustered. I've never seen her look so shy before."
