  AvgCommunicate_66973_Content_5 = {
    Text = "Hmm? I always thought Faint had such an introverted personality."
  },
  AvgCommunicate_66973_Content_6 = {
    Text = "No, actually my sister is extremely strong-willed and decisive!"
  },
  AvgCommunicate_66973_Content_7 = {
    Text = "In my moments of confusion and fragility, my sister always gave me advice and comforted me with gentle head pats."
  },
  AvgCommunicate_66973_Content_8 = {
    Text = "I see, that's unexpected."
  },
  AvgCommunicate_66973_Content_9 = {
    Text = "But now we no longer face survival threats, and my sister can finally make friends openly."
