  AvgCommunicate_66984_Content_16 = {
    Text = "You're always so reliable and considerate, my knight."
  },
  AvgCommunicate_66984_Content_2 = {
    Text = "What has got you stumped, Lady Sorel?"
  },
  AvgCommunicate_66984_Content_3 = {
    Text = "I'm all ears."
  },
  AvgCommunicate_66984_Content_4 = {
    Text = "In a few days, I'm attending a dinner party, you know, a gathering of refined yet pretentious people doing nothing."
  },
  AvgCommunicate_66984_Content_5 = {
    Text = "Annoyingly, recently a rude guy keeps bothering me; he's also attending the ball and even boldly invited me to be his partner."
  },
  AvgCommunicate_66984_Content_6 = {
    Text = "Such an annoying person. Shall I take care of him for you, madam?"
  },
  AvgCommunicate_66984_Content_7 = {
    Text = "Heh heh, you're getting better at making jokes."
  },
  AvgCommunicate_66984_Content_8 = {
    Text = "Unfortunately, not now. The adult world is always so complicated. However, I've already declined his invitation."
  },
  AvgCommunicate_66984_Content_9 = {
    Text = "So the issue is resolved?"
  },
  AvgCommunicate_66984_Option_14 = {
    Text = "It's my pleasure, madam."
  },
  AvgCommunicate_66984_Option_2 = {
    Text = "What has got you stumped, Lady Sorel?"
  },
  AvgCommunicate_66984_Option_3 = {
    Text = "I'm all ears."
  },
  AvgCommunicate_66984_Option_6 = {
    Text = "Such an annoying person. Shall I take care of him for you, madam?"
  },
  AvgCommunicate_66984_Option_9 = {
    Text = "So the issue is resolved?"
  },
  AvgCommunicate_66985_Content_1 = {
    Text = "My little knight, thanks to your help at the last ball, I've finally managed to get rid of that annoying person."
  },
  AvgCommunicate_66985_Content_10 = {
    Text = "Wanna make a wish? Then wish for a grand candlelight dinner with the beautiful Lady Sorel."
  },
  AvgCommunicate_66985_Content_11 = {
    Text = "It's just you and me. No need to socialize with anyone else."
  },
  AvgCommunicate_66985_Content_12 = {
    Text = "As you wish, you sly little thing."
  },
  AvgCommunicate_66985_Content_13 = {
    Text = "What would you like to eat? Tell me, and I'll taste it with you."
  },
  AvgCommunicate_66985_Content_14 = {
    Text = "This really tests the imagination of someone who eats in the canteen every day. Let me try the dish that the lady loves the most."
  },
  AvgCommunicate_66985_Content_15 = {
    Text = "Heh, you're such a charming child."
  },
  AvgCommunicate_66985_Content_16 = {
    Text = "I will be awaiting your arrival at my mansion."
  },
  AvgCommunicate_66985_Content_2 = {
    Text = "To express my gratitude for your kindness and generosity, I would like to do something for you as a token of my appreciation."
  },
  AvgCommunicate_66985_Content_3 = {
    Text = "You are too kind, Lady Sorel. I thought our relationship no longer required expressions of gratitude."
  },
  AvgCommunicate_66985_Content_4 = {
    Text = "I really dislike expressing gratitude verbally; most of the time, it's just insincere pleasantries."
  },
  AvgCommunicate_66985_Content_5 = {
    Text = "But an opportunity to make any request of me—aren't you interested?"
  },
  AvgCommunicate_66985_Content_6 = {
    Text = "Wow, any request? If those noble gentlemen hear this, they'll be so jealous."
  },
  AvgCommunicate_66985_Content_7 = {
    Text = "You will always deserve special treatment from me."
  },
  AvgCommunicate_66985_Content_8 = {
    Text = "This really has me stumped... I'm so conflicted. If I go all out and ask for a mansion, will the school find out?"
  },
  AvgCommunicate_66985_Content_9 = {
    Text = "It's all right. I'll take care of everything, so feel free to make your wish."
  },
  AvgCommunicate_66985_Option_10 = {
    Text = "Would you like to make a wish?"
  },
  AvgCommunicate_66985_Option_14 = {
    Text = "Then let me try the dish that the lady loves the most."
  },
  AvgCommunicate_66985_Option_3 = {
    Text = "You are too kind, Lady Sorel."
  },
  AvgCommunicate_66985_Option_6 = {
    Text = "Wow, any requests?"
  },
  AvgCommunicate_66985_Option_8 = {
    Text = "This really has me stumped..."
  },
  AvgCommunicate_66986_Content_1 = {
    Text = "I just fought Lotan. It was a draw."
  },
  AvgCommunicate_66986_Content_10 = {
    Text = "Hahaha... I think I don't have that many distracting thoughts, so let's just leave it at that for now."
  },
  AvgCommunicate_66986_Content_11 = {
    Text = "So, you're also very strong."
  },
  AvgCommunicate_66986_Content_12 = {
    Text = "It's a shame that there's always someone fishing near the waterfall. It's a bit noisy."
  },
  AvgCommunicate_66986_Content_13 = {
    Text = "One time, I walked out of the waterfall and asked him to keep it down. He got so scared that he threw the fish in my face and ran away."
  },
  AvgCommunicate_66986_Content_14 = {
    Text = "I don't know if he will come again."
  },
  AvgCommunicate_66986_Content_15 = {
    Text = "Mm... I don't think so..."
  },
  AvgCommunicate_66986_Content_2 = {
    Text = "What's wrong with you?"
  },
  AvgCommunicate_66986_Content_3 = {
    Text = "No arguments, right?"
  },
  AvgCommunicate_66986_Content_4 = {
    Text = "Nothing, just a friendly sparring among warriors."
  },
  AvgCommunicate_66986_Content_5 = {
    Text = "Previously, she said my battle wasn't pure enough. Now, I think I understand."
  },
  AvgCommunicate_66986_Content_6 = {
    Text = "I've found a way to become purer. I'm stronger now."
  },
  AvgCommunicate_66986_Content_7 = {
    Text = "That's good, but what method should be used to achieve purity?"
  },
  AvgCommunicate_66986_Content_8 = {
    Text = "Stand beneath the waterfall and let the flowing water wash away your distracting thoughts."
  },
  AvgCommunicate_66986_Content_9 = {
