  AvgCommunicate_66987_Content_1 = {
    Text = "Keeper, do you know any recipes involving fish?"
  },
  AvgCommunicate_66987_Content_10 = {
    Text = "What a kind and gentle old lady."
  },
  AvgCommunicate_66987_Content_11 = {
    Text = "Mm, so I also want to learn how to cook fish. Next time, I'll make it for her."
  },
  AvgCommunicate_66987_Content_12 = {
    Text = "So touching! We must do this! I'll go question the cafeteria chef right now!"
  },
  AvgCommunicate_66987_Content_13 = {Text = "Thank you."},
  AvgCommunicate_66987_Content_2 = {
    Text = "Recipe?? Are you going to cook?"
  },
  AvgCommunicate_66987_Content_3 = {
    Text = "Mm, the area around the waterfall has been quiet for a long time since I scared off the last fisherman."
  },
  AvgCommunicate_66987_Content_4 = {
    Text = "An old lady has been coming here to fish lately. She's quiet, so I haven't shown up."
  },
  AvgCommunicate_66987_Content_5 = {
    Text = "Later, she lit a fire to grill the fish she had caught."
  },
  AvgCommunicate_66987_Content_6 = {
    Text = "Since it smelled so good, my stomach growled a little, and she noticed."
  },
  AvgCommunicate_66987_Content_7 = {
    Text = "Huh? Was she scared by you too?"
  },
  AvgCommunicate_66987_Content_8 = {
    Text = "No, she invited me to eat roasted fish together. It was delicious."
  },
  AvgCommunicate_66987_Content_9 = {
    Text = "Later, she started bringing a small pot for fishing and then shared fish soup with me to eat together."
  },
  AvgCommunicate_66987_Option_10 = {
    Text = "What a kind and gentle old lady."
  },
  AvgCommunicate_66987_Option_12 = {
    Text = "So touching! We must do this! I'll go question the cafeteria chef right now!"
  },
  AvgCommunicate_66987_Option_2 = {
    Text = "Recipe?? Are you going to cook?"
  },
  AvgCommunicate_66987_Option_7 = {
    Text = "Huh? Was she scared by you too?"
  },
  AvgCommunicate_66988_Content_1 = {
    Text = "Recently, I came into some money, but I almost died. Fortunately, the Goddess of Luck is always by my side."
  },
  AvgCommunicate_66988_Content_10 = {
    Text = "As a result, during our fight, the triggered trap accidentally hit him."
  },
  AvgCommunicate_66988_Content_11 = {Text = "Huh?"},
  AvgCommunicate_66988_Content_12 = {
    Text = "I performed emergency bleeding control on him and then took him to the police station alive."
  },
  AvgCommunicate_66988_Content_13 = {
    Text = "The police gave me a bonus, and the criminal was sent back to prison. I heard that his sentence has been changed to life imprisonment."
  },
  AvgCommunicate_66988_Content_14 = {
    Text = "He could have been released in a few more years. Why do something foolish? Sigh..."
  },
  AvgCommunicate_66988_Content_15 = {
    Text = "Hard to say whether you or he suffered more..."
  },
  AvgCommunicate_66988_Content_16 = {
    Text = "But I remember that yesterday you were chased by people from the gambling hall to collect debts. Where is your prize money?"
  },
  AvgCommunicate_66988_Content_17 = {
    Text = "Hahaha... After all, my luck is finite, and if I exhaust it early, I might fumble a few times at the gambling table..."
  },
  AvgCommunicate_66988_Content_18 = {
    Text = "Hearing this, I suddenly felt much more at ease."
  },
  AvgCommunicate_66988_Content_2 = {
    Text = "What's going on??"
  },
  AvgCommunicate_66988_Content_3 = {
    Text = "You know, I take on detective commissions on the side, and my high success rate keeps me in demand."
  },
  AvgCommunicate_66988_Content_4 = {
    Text = "But conversely, those I sent to prison hate me to the point of grinding their teeth."
  },
  AvgCommunicate_66988_Content_5 = {
    Text = "Because they truly lost in such an inexplicable manner."
  },
  AvgCommunicate_66988_Content_6 = {
    Text = "The other day, a criminal broke out of prison and hid at my usual gambling den for several days. Finally, they caught me."
  },
  AvgCommunicate_66988_Content_7 = {
    Text = "Is this revenge against me?!"
  },
  AvgCommunicate_66988_Content_8 = {
    Text = "Exactly, he had been following me for a long time and finally cornered me in an alley."
  },
  AvgCommunicate_66988_Content_9 = {
    Text = "He set a trap in the alley, intending to kill me."
  },
  AvgCommunicate_66988_Option_11 = {Text = "Huh?"},
  AvgCommunicate_66988_Option_15 = {
    Text = "Hard to say whether you or he suffered more..."
  },
  AvgCommunicate_66988_Option_18 = {
    Text = "Hearing this, I suddenly felt much more at ease."
  },
  AvgCommunicate_66988_Option_2 = {
    Text = "What's going on??"
  },
  AvgCommunicate_66988_Option_5 = {
    Text = "Because they truly lost in such an inexplicable manner."
  },
  AvgCommunicate_66988_Option_7 = {
    Text = "Is this revenge against me?!"
  },
  AvgCommunicate_66989_Content_1 = {
    Text = "Keeper, the question you asked me about investigator crisis management solutions has been organized."
  },
  AvgCommunicate_66989_Content_10 = {
    Text = "I will care for your needs more than Ramona did, but don't forget, I was her too."
  },
  AvgCommunicate_66989_Content_11 = {
    Text = "If you want to fool me, you'd better keep practicing."
  },
  AvgCommunicate_66989_Content_12 = {
    Text = "Sigh... My sincere feelings were misplaced!"
  },
  AvgCommunicate_66989_Content_13 = {
    Text = "So, the assignment—ah, no, I mean the question—can you give me some hints on how to approach it?"
  },
  AvgCommunicate_66989_Content_14 = {Text = "Ramona?"},
  AvgCommunicate_66989_Content_15 = {Text = "Ramona—"},
  AvgCommunicate_66989_Content_2 = {
    Text = "Great! I knew you were the most reliable."
  },
  AvgCommunicate_66989_Content_3 = {
    Text = "Thanks, but wouldn't it be the same if you asked Ramona in your world about these questions? Why come to me?"
  },
  AvgCommunicate_66989_Content_4 = {
    Text = "You know, Ramona is very meticulous. If I ask her directly, she'll definitely make me figure it out on my own."
  },
  AvgCommunicate_66989_Content_5 = {
    Text = "But I think learning progresses the fastest through discussion and reference!"
  },
  AvgCommunicate_66989_Content_6 = {
    Text = "I understand."
  },
  AvgCommunicate_66989_Content_7 = {
