  AvgCommunicate_66989_Content_8 = {Text = "?!"},
  AvgCommunicate_66989_Content_9 = {
    Text = "N-no, of course not, why would it be? Haha..."
  },
  AvgCommunicate_66989_Option_12 = {
    Text = "Sigh... My sincere feelings were misplaced!"
  },
  AvgCommunicate_66989_Option_2 = {
    Text = "Great! I knew you were the most reliable."
  },
  AvgCommunicate_66989_Option_4 = {
    Text = "You know..."
  },
  AvgCommunicate_66989_Option_8 = {Text = "?!"},
  AvgCommunicate_66990_Content_1 = {
    Text = "Kiiper, everyone's names are so difficult to write. I can't remember the spelling!"
  },
  AvgCommunicate_66990_Content_10 = {
    Text = "Then, then I'll change it! You mustn't tell!"
  },
  AvgCommunicate_66990_Content_11 = {
    Text = "Alright, alright, what are Aigis and Lily's names?"
  },
  AvgCommunicate_66990_Content_12 = {
    Text = "Of course, their names are Aigis and Lily. They are friends. Friends can't have the same name!"
  },
  AvgCommunicate_66990_Content_13 = {
    Text = "Then why am I called the Kiiper..."
  },
  AvgCommunicate_66990_Content_14 = {
