    Text = "Keeper!! Brown is missing! Have you seen it?"
  },
  AvgCommunicate_66991_Content_10 = {
    Text = "This will have to do for now... Thank you, Keeper."
  },
  AvgCommunicate_66991_Content_11 = {
    Text = "Now you're being polite? I'll just get dressed and head out... Wait."
  },
  AvgCommunicate_66991_Content_12 = {
    Text = "Why is there a familiar tail in my pile of clothes..."
  },
  AvgCommunicate_66991_Content_13 = {
    Text = "Brown?! Is Brown with you?"
  },
  AvgCommunicate_66991_Content_14 = {
    Text = "Yes, no need to look. It's tangled in my shirt and has my sock in its mouth. Do you have any ideas?"
  },
  AvgCommunicate_66991_Content_15 = {
    Text = "This, this is definitely a mouse's hobby. It has nothing to do with me!"
  },
  AvgCommunicate_66991_Content_16 = {
    Text = "Fine, I'll just compensate you with a new pair of socks."
  },
  AvgCommunicate_66991_Content_2 = {
    Text = "Brown? Hasn't it always been with you?"
  },
  AvgCommunicate_66991_Content_3 = {
    Text = "Most of the time, yes, but sometimes it goes out to... hunt for something, and usually comes back within half a day. But I haven't seen it all day!"
