  AvgCommunicate_66991_Content_5 = {
    Text = "Usually, the kitchen is where they go most often, but those idiots can't possibly catch Brown."
  },
  AvgCommunicate_66991_Content_6 = {
    Text = "It's also possible to find shiny trinkets in the lab, but I've already checked everywhere and found no trace of Brown."
  },
  AvgCommunicate_66991_Content_7 = {
    Text = "...So that's why the lab keeps losing parts—a supernatural event."
  },
  AvgCommunicate_66991_Content_8 = {
    Text = "I've walked around the campus several times. Could it be... was it eaten by that damn school cat?!!"
  },
  AvgCommunicate_66991_Content_9 = {
    Text = "Hmm, that campus cat probably doesn't like this flavor... How about I make some mouse-search posters and put them up around campus? If everyone helps, we'll definitely find it!"
