  AvgCommunicate_66993_Content_5 = {
    Text = "Wow, that's impressive!"
  },
  AvgCommunicate_66993_Content_6 = {
    Text = "No, it's nothing special..."
  },
  AvgCommunicate_66993_Content_7 = {
    Text = "But now I'm skilled enough to knit more complex things, so I want to knit a sweater for you, Keeper!"
