  AvgCommunicate_66995_Content_1 = {Text = "Hey."},
  AvgCommunicate_66995_Content_10 = {
    Text = "If you don't keep her away from me, you'll get to experience my flail up close."
  },
  AvgCommunicate_66995_Content_2 = {
    Text = "Don't call me \"hey\"..."
  },
  AvgCommunicate_66995_Content_3 = {
    Text = "You actually took the initiative to seek me out."
  },
  AvgCommunicate_66995_Content_4 = {
    Text = "Enough talk. Get rid of that woman named Lotan."
  },
  AvgCommunicate_66995_Content_5 = {
    Text = "The lunatic has been bothering me for a month."
  },
  AvgCommunicate_66995_Content_6 = {
    Text = "And no matter how hard we hit, it just won't die. So annoying!"
  },
  AvgCommunicate_66995_Content_7 = {
    Text = "Uh, it seems that you're really skilled."
  },
  AvgCommunicate_66995_Content_8 = {
    Text = "Lotan rarely encounters an opponent who can keep fighting her, so she must be very happy."
  },
  AvgCommunicate_66995_Content_9 = {
    Text = "Hmph, flattery won't work on me."
  },
  AvgCommunicate_66995_Option_2 = {
    Text = "First, my name is not \"Hey\"..."
  },
  AvgCommunicate_66995_Option_3 = {
    Text = "Second, you actually came looking for me."
  },
  AvgCommunicate_66995_Option_7 = {
    Text = "Uh, it seems that you're really skilled."
  },
  AvgCommunicate_66996_Content_1 = {
    Text = "Mythag is such a boring place."
  },
  AvgCommunicate_66996_Content_10 = {
    Text = "Then good luck getting what you want. If you ever wish to return, the gates of Mythag will always be open to you."
  },
  AvgCommunicate_66996_Content_2 = {
    Text = "A group of self-proclaimed righteous individuals, imprisoning beasts fitted with collars."
  },
  AvgCommunicate_66996_Content_3 = {
    Text = "I can't figure out why I used to participate in your boring games, but considering her weakness, it all makes sense."
  },
  AvgCommunicate_66996_Content_4 = {
    Text = "You've never been steadfastly protected by someone, so you can't understand the feeling and significance of being protected."
  },
  AvgCommunicate_66996_Content_5 = {
    Text = "Helot is an outstanding warrior. She simply chose to accept the warmth and help offered by others."
  },
  AvgCommunicate_66996_Content_6 = {
    Text = "Ha, do as you wish. If she chooses to wear the collar, let her stay."
  },
  AvgCommunicate_66996_Content_7 = {
    Text = "I'm leaving. Staying here will only dull the warrior."
  },
  AvgCommunicate_66996_Content_8 = {
    Text = "Fine, I guess you won't tell me where you're going."
  },
  AvgCommunicate_66996_Content_9 = {
    Text = "Wherever there is power, that's where I'll go."
  },
  AvgCommunicate_66996_Option_10 = {
    Text = "Then good luck obtaining what you desire."
  },
  AvgCommunicate_66996_Option_4 = {
    Text = "You've never been steadfastly protected by someone, so you can't understand the feeling and significance of being protected."
  },
  AvgCommunicate_66996_Option_8 = {
