  },
  AvgCommunicate_66997_Content_1 = {
    Text = "Hey, I heard Murphy hasn't been attending class recently. What's going on?"
  },
  AvgCommunicate_66997_Content_10 = {
    Text = "Of course, I'll just seize one back."
  },
  AvgCommunicate_66997_Content_11 = {
    Text = "Hello, is this the police? Someone is about to commit a crime again."
  },
  AvgCommunicate_66997_Content_12 = {
    Text = "Fine, I'll buy one, alright? You meddling fool."
  },
  AvgCommunicate_66997_Content_13 = {
    Text = "Remember, I'm watching you. If you try anything funny with Murphy... Hmph."
  },
  AvgCommunicate_66997_Content_2 = {
    Text = "She ate too many little cakes and got a stomachache. But why don't you ask her yourself?"
  },
  AvgCommunicate_66997_Content_3 = {
    Text = "Enough talk. Did you do something? I saw you kept buying her cakes."
  },
  AvgCommunicate_66997_Content_4 = {
    Text = "What does that have to do with me? She was just greedy and ate the leftover cake she hadn't thrown out the previous day."
  },
  AvgCommunicate_66997_Content_5 = {
    Text = "Wait, how is this even any of your business?"
  },
  AvgCommunicate_66997_Content_6 = {
    Text = "I doubt you'd dare."
  },
  AvgCommunicate_66997_Content_7 = {
    Text = "Hmph, what's so special about a few cakes? I'll find a chef to make them for her every single day."
  },
  AvgCommunicate_66997_Content_8 = {
    Text = "You don't actually think you're her father, do you? I never expected you to have such a fatherly side."
  },
  AvgCommunicate_66997_Content_9 = {
    Text = "Wait, how are you planning to \"find\" a chef?"
  },
  AvgCommunicate_66997_Option_11 = {
    Text = "Hello, is this the police? Someone is about to commit a crime again."
  },
  AvgCommunicate_66997_Option_2 = {
    Text = "She ate too many little cakes and got a stomachache."
  },
  AvgCommunicate_66997_Option_4 = {
    Text = "What does that have to do with me?"
  },
  AvgCommunicate_66997_Option_8 = {
    Text = "I never expected you to show such a fatherly side."
  },
  AvgCommunicate_66998_Content_1 = {
    Text = "The journey of the strong is truly lonely."
  },
  AvgCommunicate_66998_Content_10 = {
    Text = "For the moment, it's unclear whether you've done something good or bad..."
  },
  AvgCommunicate_66998_Content_11 = {
    Text = "Hmph, I merely did what the strong ought to do."
  },
  AvgCommunicate_66998_Content_12 = {
    Text = "The underworld here is a bit dull now. What should I do next..."
  },
  AvgCommunicate_66998_Content_13 = {
    Text = "Whatever you're planning, I'll inform the police to keep a close watch on you."
  },
  AvgCommunicate_66998_Content_2 = {
    Text = "A journey? What have you done? Are you at the police station again?"
  },
  AvgCommunicate_66998_Content_3 = {
    Text = "What a joke! As if those fools could ever trap me."
  },
  AvgCommunicate_66998_Content_4 = {
    Text = "After the last incident, I have now successfully conquered half of Londinium's underworld."
  },
  AvgCommunicate_66998_Content_5 = {
    Text = "It's a pity that the gangs here are much weaker than my Philistines; they will ultimately fail to achieve greatness."
  },
  AvgCommunicate_66998_Content_6 = {
    Text = "Gang?? What kind of illegal activities have you been involved in?"
  },
  AvgCommunicate_66998_Content_7 = {
    Text = "What? If fighting the mob is considered wrong, then there are probably no good people left in the world."
  },
  AvgCommunicate_66998_Content_8 = {
    Text = "To be honest, Mythag or that police department owes me a medal of honor."
  },
  AvgCommunicate_66998_Content_9 = {
    Text = "Now this group has been beaten into submission by me. Haven't you noticed that the city's security has improved?"
  },
  AvgCommunicate_66998_Option_10 = {
    Text = "For the moment, it's unclear whether you've done something good or bad..."
  },
  AvgCommunicate_66998_Option_13 = {
    Text = "Whatever you're planning, I'll inform the police to keep a close watch on you."
  },
  AvgCommunicate_66998_Option_2 = {
    Text = "A journey? What have you done? Are you at the police station again?"
