  AvgCommunicate_66999_Content_1 = {
    Text = "{Male=Mr.,Female=Miss} %player%, I was recently invited by Mythag University to help record the class transition music."
  },
  AvgCommunicate_66999_Content_10 = {
    Text = "If I must specify what's special about it, it must be because it's brimming with my need to protect you."
  },
  AvgCommunicate_66999_Content_11 = {
    Text = "Actually, I've always had a bit of trouble getting up. If I had some rousing music, it would probable be easier to get out of bed!"
  },
  AvgCommunicate_66999_Content_12 = {
    Text = "Rousing music? Understood."
  },
  AvgCommunicate_66999_Content_13 = {
    Text = "Even though I think it's more important to get quality sleep, you shoulder such numerous burdens that business is unavoidable."
  },
  AvgCommunicate_66999_Content_14 = {
    Text = "May this march lend you strength!"
  },
  AvgCommunicate_66999_Content_2 = {
    Text = "During the recording session, Professor Doll also mentioned that the school had developed a new type of tape recorder. It's small and portable for missions, has clear audio, and features both recording and playback functions."
  },
  AvgCommunicate_66999_Content_3 = {
    Text = "When I saw it, I thought of you. If you'd like, I can make a recording of the music you like to listen to."
  },
  AvgCommunicate_66999_Content_4 = {
    Text = "That way, even when I'm not by your side, you need not worry about lacking music to soothe your soul."
  },
  AvgCommunicate_66999_Content_5 = {
    Text = "Hameln... I'm so moved!"
  },
  AvgCommunicate_66999_Content_6 = {
    Text = "It's simply fulfilling my duty. Well then, is there anything you wish to listen to?"
  },
  AvgCommunicate_66999_Content_7 = {
    Text = "Speaking of which, I always sleep well whenever you perform a lullaby."
  },
  AvgCommunicate_66999_Content_8 = {
    Text = "What's makes it so special?"
  },
  AvgCommunicate_66999_Content_9 = {
    Text = "You wish to hear that style? Understood."
  },
  AvgCommunicate_66999_Option_11 = {
    Text = "Energetic music."
  },
  AvgCommunicate_66999_Option_5 = {
    Text = "Hameln... I'm so moved!"
  },
  AvgCommunicate_66999_Option_7 = {
    Text = "Relaxing music."
  },
  AvgCommunicate_67000_Content_1 = {
    Text = "{Male=Mr.,Female=Miss} %player%. I've recently composed a new piece and would like to invite you to give it a listen and critique in your free time."
  },
  AvgCommunicate_67000_Content_10 = {
    Text = "Ah, such requests are rather austere. My apologies for being inconsiderate."
  },
  AvgCommunicate_67000_Content_11 = {
    Text = "How about next time I play by your bedside and you allow me to observe and record your sleep."
  },
  AvgCommunicate_67000_Content_12 = {
    Text = "I hope you fall asleep every time under my protection."
  },
  AvgCommunicate_67000_Content_2 = {
    Text = "You're too kind Hameln, but how can a half-baked amateur like me be qualified to critique your work?"
  },
