  AvgCommunicate_67006_Content_1 = {
    Text = "I find that, although technological progress and business development remain dull, many new types of pillows have emerged."
  },
  AvgCommunicate_67006_Content_10 = {
    Text = "That salesperson called me a natural-born sleep tester and insisted I test pillows for them long-term."
  },
  AvgCommunicate_67006_Content_11 = {
    Text = "They're asking you to work? If Miryam finds out, she might just kill them."
  },
  AvgCommunicate_67006_Content_12 = {
    Text = "I originally wanted to refuse, but he said that test sleepers could take all new products home for free to try out."
  },
  AvgCommunicate_67006_Content_13 = {
    Text = "Seeing his sincerity, I agreed."
  },
  AvgCommunicate_67006_Content_14 = {
    Text = "Never expected you'd be bribed by a pillow... Ah, I mean, what a truly kind King."
  },
  AvgCommunicate_67006_Content_2 = {
    Text = "The other day, I passed by the department store in Londinium and saw they were promoting a series of new pillows."
