  AvgCommunicate_67013_Option_7 = {Text = "..."},
  AvgCommunicate_67014_Content_1 = {
    Text = "{Male=Mr.,Female=Miss} Keeper, sometimes I wonder if everything I have tried to do for my King has truly satisfied him."
  },
  AvgCommunicate_67014_Content_10 = {
    Text = "But I believe the only thing the gods can truly feel is the passionate, devout heart that their followers dedicate to them."
  },
  AvgCommunicate_67014_Content_11 = {
    Text = "So, what you did is perhaps not the most important part; what matters is the heart you put into it. After all, Tulu never stopped you, did he?"
  },
  AvgCommunicate_67014_Content_12 = {
    Text = "I never expected to be enlightened by an unbeliever like you. Your words have left a deep impression on me. Thank you."
  },
  AvgCommunicate_67014_Content_2 = {
    Text = "Is the path I have chosen truly the right one?"
  },
  AvgCommunicate_67014_Content_3 = {
    Text = "I never expected you to reflect on yourself one day."
  },
  AvgCommunicate_67014_Content_4 = {
    Text = "Because I, too, feel confused, weary, and disheartened. If all that I do is right, why has the King not responded to me?"
  },
  AvgCommunicate_67014_Content_5 = {
    Text = "Though I am not as devout as you, I believe that what followers do for a God is not necessarily what the God needs."
  },
  AvgCommunicate_67014_Content_6 = {
    Text = "What did you say?"
  },
  AvgCommunicate_67014_Content_7 = {
    Text = "Hey, hey, don't rush. I haven't finished speaking yet."
  },
  AvgCommunicate_67014_Content_8 = {
    Text = "The difference between mortals and gods is akin to that between ants and humans. I don't believe humans can fully comprehend the needs of gods."
  },
  AvgCommunicate_67014_Content_9 = {
    Text = "Ants... Perhaps you're right."
  },
  AvgCommunicate_67014_Option_10 = {
    Text = "But I believe..."
  },
  AvgCommunicate_67014_Option_3 = {
    Text = "I never expected you to reflect on yourself one day."
  },
  AvgCommunicate_67014_Option_5 = {
    Text = "Though my faith isn't as devout as yours..."
  },
  AvgCommunicate_67014_Option_7 = {
    Text = "Hey, hey, don't rush. I haven't finished speaking yet."
  },
  AvgCommunicate_67015_Content_1 = {
    Text = "Keeper, the lecture I held on campus and the brochures I printed have been well received."
  },
  AvgCommunicate_67015_Content_10 = {
    Text = "Miss Sanga? I rarely see her, but I've heard she's an outstanding sculptor."
  },
  AvgCommunicate_67015_Content_11 = {
    Text = "If she is willing to sculpt for our Lord, it would be perfect; the Divine Realm will shelter her."
  },
  AvgCommunicate_67015_Content_2 = {
    Text = "They began to worship my great lord. Some followers asked me for miniature statues, so they could place them in their rooms for prayer and worship."
  },
  AvgCommunicate_67015_Content_3 = {
    Text = "I think they make sense. Where can I find a craftsman to customize a batch of such statues?"
  },
  AvgCommunicate_67015_Content_4 = {
    Text = "Mini statuette? Sounds a bit strange..."
  },
  AvgCommunicate_67015_Content_5 = {
    Text = "What's wrong? The craftsmanship of these statues is exquisite. Doesn't Mythag have such skilled artisans?"
  },
  AvgCommunicate_67015_Content_6 = {
    Text = "It's not the craftsman's fault; it just seems they want these statues for something other than prayer and worship..."
  },
  AvgCommunicate_67015_Content_7 = {
    Text = "Impossible, I've seen their fervor for my master. They even care about every detail of my master's preferences and lifestyle."
  },
  AvgCommunicate_67015_Content_8 = {
    Text = "Then it's even more right... Whatever, as long as you're happy."
  },
  AvgCommunicate_67015_Content_9 = {
    Text = "I'll ask Sanga if she's willing to make this batch of statues."
  },
  AvgCommunicate_67015_Option_4 = {
    Text = "Mini statuette? Sounds a bit strange..."
  },
  AvgCommunicate_67015_Option_6 = {
    Text = "It's not the craftsman's issue..."
  },
  AvgCommunicate_67015_Option_8 = {
