  AvgCommunicate_67016_Content_1 = {
    Text = "Sigh, Keeper, I am here to explain my negligence to you and Noble Dexter in the hope of gaining your forgiveness."
  },
  AvgCommunicate_67016_Content_10 = {
    Text = "Cough... Though it's tragic, it's not your fault. Don't blame yourself."
  },
  AvgCommunicate_67016_Content_11 = {
    Text = "No, it's my fault for not paying attention. I will publicly issue a self-criticism and strengthen daily management."
  },
  AvgCommunicate_67016_Content_2 = {
    Text = "Due to my poor management, two patients in the sanatorium were severely poisoned. Fortunately, they have now been stabilized after emergency treatment."
  },
  AvgCommunicate_67016_Content_3 = {
    Text = "Huh? What's going on?"
  },
  AvgCommunicate_67016_Content_4 = {
    Text = "Yes, there is a small pond behind the sanatorium, rarely visited."
  },
  AvgCommunicate_67016_Content_5 = {
    Text = "You know how much I love water. On busy workdays, I quietly sink into the pond at night, enjoying a moment of tranquility underwater."
  },
  AvgCommunicate_67016_Content_6 = {
    Text = "Mm... Understandable. There's no job without stress."
  },
  AvgCommunicate_67016_Content_7 = {
    Text = "Perhaps I've visited too frequently, and the toxins within me have spread to the pond and the fish in it."
  },
  AvgCommunicate_67016_Content_8 = {
    Text = "This pond was not in the patients' activity area, but two greedy patients sneaked there to fish and grill their catch two days ago."
  },
  AvgCommunicate_67016_Content_9 = {
    Text = "By the time the medical staff found them, they were already foaming at the mouth and had passed out on the ground..."
  },
  AvgCommunicate_67016_Option_10 = {
    Text = "Cough... Though it's tragic, it's not your fault. Don't blame yourself."
  },
  AvgCommunicate_67016_Option_3 = {
    Text = "Huh? What's going on?"
  },
  AvgCommunicate_67016_Option_6 = {
    Text = "Mm... Understandable. There's no job without stress."
  },
  AvgCommunicate_67017_Content_1 = {
    Text = "Keeper, a visitor to Mythag accidentally overheard me singing while I was practicing."
  },
  AvgCommunicate_67017_Content_10 = {
    Text = "You love singing and performing. Why not let more people hear your voice?"
  },
  AvgCommunicate_67017_Content_11 = {
    Text = "Love... I understand. Thank you, Keeper."
  },
  AvgCommunicate_67017_Content_12 = {
    Text = "I'll try to shine on this planet once more."
  },
  AvgCommunicate_67017_Content_2 = {
    Text = "Now the other party is inviting me to collaborate with his company to release some records. Should I agree?"
  },
  AvgCommunicate_67017_Content_3 = {
    Text = "I think it's possible. I remember you were once a famous singer, right?"
  },
  AvgCommunicate_67017_Content_4 = {
    Text = "Yes, my songs were once all the rage on the Desolate, our home planet, but most of the time, it was merely for trading with the nobility."
  },
  AvgCommunicate_67017_Content_5 = {
    Text = "Now that I have my sister back, I no longer need anything."
  },
  AvgCommunicate_67017_Content_6 = {
    Text = "And you? When you sing, do you still feel happy?"
  },
  AvgCommunicate_67017_Content_7 = {
    Text = "Happiness... Perhaps it is happiness, after all, all I can do now is sing."
  },
  AvgCommunicate_67017_Content_8 = {
    Text = "No, Tinct. If it weren't true love, no one would practice singing every day."
  },
  AvgCommunicate_67017_Content_9 = {
    Text = "It's only natural to stick to what you love."
  },
  AvgCommunicate_67017_Option_3 = {
    Text = "I think it's possible. I remember you were once a famous singer, right?"
  },
  AvgCommunicate_67017_Option_6 = {
    Text = "And you? When you sing, do you still feel happy?"
