  AvgCommunicate_67018_Content_1 = {
    Text = "Pale Herald, I wanted to inform you that I am about to visit Mythag."
  },
  AvgCommunicate_67018_Content_2 = {
    Text = "A previous visit seemed to provide some minor help, and I was invited to return for a chat with everyone in the hall."
  },
  AvgCommunicate_67018_Content_3 = {
    Text = "If you happen to have some free time, I hope to see you on campus."
  },
  AvgCommunicate_67018_Content_4 = {
    Text = "I'd be more than happy to!"
  },
  AvgCommunicate_67018_Content_5 = {
    Text = "Great, I'll set aside some time just for you to listen to everything you want to tell me."
  },
  AvgCommunicate_67018_Content_6 = {
    Text = "Are we meeting alone?"
  },
  AvgCommunicate_67018_Content_7 = {
    Text = "Yes, after all, this isn't a religious service, just a gathering of friends, right?"
  },
  AvgCommunicate_67018_Content_8 = {
    Text = "No problem, I'll show you around Mythag's spots. Maybe you'd like to try the Awakener's cafeteria?"
