  AvgCommunicate_67018_Option_8 = {
    Text = "No problem!"
  },
  AvgCommunicate_67019_Content_1 = {
    Text = "Pale Herald, a grand mass will soon be held in the Church district."
  },
  AvgCommunicate_67019_Content_10 = {
    Text = "Your sincere heart warms me, so I will no longer refuse."
  },
  AvgCommunicate_67019_Content_11 = {
    Text = "Please come whenever you have free time and help me with some simple cleaning and arranging."
  },
  AvgCommunicate_67019_Content_12 = {
    Text = "No problem, see you then!"
  },
  AvgCommunicate_67019_Content_13 = {
    Text = "Thank you once again, Pale Messenger. May the Father God protect your path forward."
  },
  AvgCommunicate_67019_Content_2 = {
    Text = "I will preside over the ceremony and share the teachings of the Father."
  },
  AvgCommunicate_67019_Content_3 = {
    Text = "Believers from Londinium and the surrounding areas will come, and you are welcome to join the thanksgiving if you are interested."
  },
  AvgCommunicate_67019_Content_4 = {
    Text = "I'd love to! But considering the number of believers, preparing for this Mass must have been quite challenging."
  },
  AvgCommunicate_67019_Content_5 = {
    Text = "You're always so thoughtful, kind, and considerate."
  },
  AvgCommunicate_67019_Content_6 = {
    Text = "Indeed, preparing everything needed to ensure everyone feels the Father's grace is quite a lot."
  },
  AvgCommunicate_67019_Content_7 = {
    Text = "But don't worry, I have extensive experience in presiding over masses and can handle these trivial matters with ease."
  },
  AvgCommunicate_67019_Content_8 = {
    Text = "No matter how experienced one is, no one has three heads and six arms. If possible, let me help you in advance!"
  },
  AvgCommunicate_67019_Content_9 = {
    Text = "After all, for such a grand event, the more meticulous the preparation, the better."
  },
  AvgCommunicate_67019_Option_12 = {
    Text = "No problem, see you then!"
