  AvgCommunicate_67019_Option_4 = {
    Text = "I'd be happy to!"
  },
  AvgCommunicate_67019_Option_8 = {
    Text = "If possible, let me help you in advance!"
  },
  AvgCommunicate_67020_Content_1 = {
    Text = "Sigh, ever since Mythag issued the restriction order, no sweeties have come to chat with me."
  },
  AvgCommunicate_67020_Content_10 = {
    Text = "Well, then I just have to pray that the sun sets soon."
  },
  AvgCommunicate_67020_Content_11 = {
    Text = "Ah, I can't wait to see tonight's moonlight."
  },
  AvgCommunicate_67020_Content_2 = {
    Text = "What's this rule about no visitors unless you're with me?"
  },
  AvgCommunicate_67020_Content_3 = {
    Text = "You, come on, admit it. Was this your doing—out of jealousy, did you report it to the school?"
  },
  AvgCommunicate_67020_Content_4 = {
    Text = "It was you who first tricked the students into drinking strange things..."
  },
  AvgCommunicate_67020_Content_5 = {
    Text = "That was a blessing of love. Do you really think I am that despicable?"
  },
  AvgCommunicate_67020_Content_6 = {
    Text = "I waited for you every day in loneliness... I never expected you to see me like this."
  },
  AvgCommunicate_67020_Content_7 = {
    Text = "Enough! I understand. I'll spend more time with you."
  },
  AvgCommunicate_67020_Content_8 = {
    Text = "You're such a considerate child, but I want to see you every moment, right now, without waiting even a second."
  },
  AvgCommunicate_67020_Content_9 = {
    Text = "Tonight, I'll go. Alright!"
  },
  AvgCommunicate_67020_Option_4 = {
