  AvgCommunicate_67027_Content_1 = {
    Text = "Keeper, why doesn't anyone from Mythag ask me to fulfill their wishes anymore?"
  },
  AvgCommunicate_67027_Content_10 = {
    Text = "Instead of asking for it to be directly fulfilled, people want something to dream about; to look forward to."
  },
  AvgCommunicate_67027_Content_11 = {
    Text = "Even if their wishes don't immediately come true, the very act of wishing for something can bring comfort to them."
  },
  AvgCommunicate_67027_Content_12 = {
    Text = "Unfulfilled wishes... are they really that precious?"
  },
  AvgCommunicate_67027_Content_13 = {
    Text = "I think I understand now. Starting tomorrow, I will give everyone my blessings at the school's fountain."
  },
  AvgCommunicate_67027_Content_14 = {
    Text = "Wait, why the school fountain?"
  },
  AvgCommunicate_67027_Content_15 = {
    Text = "I heard that wishing wells are popular in many places, so I turned the school fountain into one. Now everyone can come and make wishes for blessings."
  },
  AvgCommunicate_67027_Content_16 = {
    Text = "I get the logic, but it's a little strange!"
  },
  AvgCommunicate_67027_Content_2 = {
    Text = "Mm... I suppose it's because people at Mythag are pragmatic."
  },
  AvgCommunicate_67027_Content_3 = {
