  AvgCommunicate_67043_Content_1 = {
    Text = "After spending so much time in Mythag, I suddenly began to miss the moon in the desert."
  },
  AvgCommunicate_67043_Content_10 = {
    Text = "Come and create new memories with me: among flowers, in the wilderness, to see the ocean and valleys, cities, and the countryside."
  },
  AvgCommunicate_67043_Content_11 = {
    Text = "I want to create beautiful memories with you in every beautiful place. Will you join me, right?"
  },
  AvgCommunicate_67043_Content_2 = {
    Text = "So you feel homesick too?"
  },
  AvgCommunicate_67043_Content_3 = {
    Text = "Rather than homesickness, perhaps I'm simply missing the memories shared with others, and those intense emotions."
  },
  AvgCommunicate_67043_Content_4 = {
    Text = "Never expected you to be so nostalgic."
  },
  AvgCommunicate_67043_Content_5 = {
    Text = "What? Think I'm carefree and unfeeling? No, I remember every person, every warm and sweet memory."
