  AvgCommunicate_67043_Content_8 = {
    Text = "I just love seeing you so flustered; it's adorable."
  },
  AvgCommunicate_67043_Content_9 = {
    Text = "Although the bygone days evoke nostalgia, the joy of tonight is the most precious."
