  AvgCommunicate_70486_Option_9 = {Text = "Yes..."},
  AvgCommunicate_70487_Content_1 = {
    Text = "How is that weakling's recovery going?"
  },
  AvgCommunicate_70487_Content_10 = {Text = "..."},
  AvgCommunicate_70487_Content_11 = {
    Text = "I don't like her, and I don't like you. But I loathe that self-righteous Snow Mountain even more, and those who wish to use or betray me."
  },
  AvgCommunicate_70487_Content_12 = {
    Text = "That is all there is to it."
  },
  AvgCommunicate_70487_Content_2 = {
    Text = "After returning from the Snow Mountain, she received treatment, and her injuries healed very well."
  },
  AvgCommunicate_70487_Content_3 = {
    Text = "I heard about the Snow Mountain from the other version of you."
  },
  AvgCommunicate_70487_Content_4 = {
    Text = "Thank you, Helot. You are the one who helped us."
  },
  AvgCommunicate_70487_Content_5 = {
    Text = "Thank you?\" What a weak word."
  },
  AvgCommunicate_70487_Content_6 = {
    Text = "I only sought to obtain the Snow Mountain's power. It has nothing to do with helping you."
  },
  AvgCommunicate_70487_Content_7 = {
    Text = "The lives of a bunch of ants are of no concern to me."
  },
  AvgCommunicate_70487_Content_8 = {
    Text = "In the Snow Mountain, you had the chance to kill the other version of yourself, either to devour the power alone or allow the mountain to devour us all."
  },
  AvgCommunicate_70487_Content_9 = {
    Text = "But you didn't, did you?"
