  AvgCommunicate_70488_Content_2 = {
    Text = "May I ask, is there any way to help him?"
  },
  AvgCommunicate_70488_Content_3 = {
    Text = "It won't be easy, Celeste."
  },
  AvgCommunicate_70488_Content_4 = {
    Text = "Linking to an Awakener is a tremendous burden on one's body, even for a trained investigator."
