  },
  AvgCommunicate_70488_Content_9 = {
    Text = "People make wishes to me, yet I am powerless to help those around me..."
  },
  AvgCommunicate_70488_Option_3 = {
    Text = "It might be difficult, but Mythag will surely find a way."
  },
  AvgCommunicate_70489_Content_1 = {
