  AvgCommunicate_70491_Option_3 = {
    Text = "There are many regrets, but we are on the right path."
  },
  AvgCommunicate_70491_Option_8 = {
    Text = "The issue is temporarily resolved, but some regrets can never be remedied."
  },
  AvgCommunicate_70492_Content_1 = {
    Text = "I plan to hold a memorial service soon, but I am somewhat short on live fish and boats."
  },
  AvgCommunicate_70492_Content_10 = {
    Text = "Since you are aware of my past, you should already know my answer."
  },
  AvgCommunicate_70492_Content_11 = {
    Text = "If I had to do it over again, I would still do what I once did."
  },
  AvgCommunicate_70492_Content_12 = {
    Text = "The past, the present, and the future. The High Priestess of Lemuria never regrets."
  },
  AvgCommunicate_70492_Content_13 = {
    Text = "I... never had any other choice, Keeper."
  },
  AvgCommunicate_70492_Content_2 = {
    Text = "Can Mythag lend us some for a while? As the High Priestess of Lemuria, I guarantee they will be returned on time."
  },
  AvgCommunicate_70492_Content_3 = {
    Text = "No problem. I will communicate with the school for you; the school committee should approve the request."
  },
  AvgCommunicate_70492_Content_4 = {
    Text = "These items... are they for your family, or for Deborah?"
  },
  AvgCommunicate_70492_Content_5 = {
    Text = "...You know everything?"
  },
  AvgCommunicate_70492_Content_6 = {
    Text = "According to Lemurian custom, you would use live fish and boats to send your regards to those among the deceased you cherish most."
  },
  AvgCommunicate_70492_Content_7 = {
    Text = "You still cannot forget them. You still love them deeply."
  },
  AvgCommunicate_70492_Content_8 = {
    Text = "So... do you regret it, Miryam?"
  },
  AvgCommunicate_70492_Content_9 = {Text = "..."},
  AvgCommunicate_70492_Option_3 = {
    Text = "No problem."
  },
  AvgCommunicate_70492_Option_4 = {
    Text = "Is this prepared for your family, or for Deborah?"
  },
  AvgCommunicate_70492_Option_8 = {
    Text = "Do you regret it?"
  },
  AvgCommunicate_70493_Content_1 = {
    Text = "I have finished reading your will."
  },
  AvgCommunicate_70493_Content_10 = {
    Text = "I will also proudly narrate your deeds to others until... the day my Memory undergoes Dissolution."
  },
  AvgCommunicate_70493_Content_11 = {
    Text = "But as I recite your will, at this moment, regret consumes all my thoughts."
  },
  AvgCommunicate_70493_Content_12 = {
    Text = "You said you were a coward. You said you would never want to abandon us."
  },
  AvgCommunicate_70493_Content_13 = {
    Text = "But in the end, you still walked down this path."
  },
  AvgCommunicate_70493_Content_14 = {
    Text = "Father is gone. You are gone as well."
  },
  AvgCommunicate_70493_Content_15 = {
    Text = "I don't mind the lies you told. I wish you could have kept deceiving me for a little while longer. A year, a month..."
  },
  AvgCommunicate_70493_Content_16 = {
    Text = "Even if it was only for a day, the words left unspoken at least would have a chance to be said..."
  },
  AvgCommunicate_70493_Content_17 = {
    Text = "I'm really scared, %player%."
  },
  AvgCommunicate_70493_Content_18 = {
    Text = "I'm afraid that one day I'll forget your face and your name."
  },
  AvgCommunicate_70493_Content_19 = {
    Text = "I'm afraid that one day, you will completely disappear from my memory..."
  },
  AvgCommunicate_70493_Content_2 = {
    Text = "I tried to recite those words in a comforting tone, as you wished."
  },
  AvgCommunicate_70493_Content_20 = {
    Text = "But you know, I am not the kind of person who gives up."
  },
  AvgCommunicate_70493_Content_21 = {
    Text = "I can't believe you would just vanish like that."
  },
  AvgCommunicate_70493_Content_22 = {
    Text = "No matter how long I wait, I will be here, remembering. Until the day you awaken from the Black Pool, open that door, and return to this campus."
  },
  AvgCommunicate_70493_Content_23 = {
    Text = "When that time comes, I will tell you everything that happened while you were gone, as well as those unspoken words, one by one..."
  },
  AvgCommunicate_70493_Content_24 = {
    Text = "I know you must be very tired now, too tired to respond... It's alright, rest well."
  },
  AvgCommunicate_70493_Content_25 = {
    Text = "I'm waiting for you... %player%."
  },
  AvgCommunicate_70493_Content_3 = {
    Text = "I did my best. But I can't do it, %player%..."
  },
  AvgCommunicate_70493_Content_4 = {
    Text = "The Keygrave is filled with people; I can't see anyone."
  },
  AvgCommunicate_70493_Content_5 = {
    Text = "The whole world has fallen silent. Only the sound of rain remains, only you and I."
  },
  AvgCommunicate_70493_Content_6 = {
    Text = "When that door closed in front of me and those words scrolled by line by line before my eyes, all I felt was regret."
  },
  AvgCommunicate_70493_Content_7 = {
    Text = "I regret instilling those Investigator ideals in you, I regret teaching you all that Investigation Knowledge, I regret bringing you here from Yakutsk..."
  },
  AvgCommunicate_70493_Content_8 = {
    Text = "I know I shouldn't think this way."
  },
  AvgCommunicate_70493_Content_9 = {
    Text = "I am an Investigator. You saved our world from Dissolution. I should feel proud for you."
  },
  AvgCommunicate_70494_Content_1 = {
    Text = "Good day, Keeper of Mythag."
  },
  AvgCommunicate_70494_Content_10 = {
    Text = "I heard that Mythag has produced an outstanding Keeper."
  },
  AvgCommunicate_70494_Content_11 = {
    Text = "I shouldn't intrude so abruptly, but I simply can't contain my curiosity and wished to see you in person."
  },
  AvgCommunicate_70494_Content_12 = {
    Text = "You didn't disappoint me, %player%."
  },
  AvgCommunicate_70494_Content_13 = {
    Text = "What exactly do you intend to do?"
  },
  AvgCommunicate_70494_Content_14 = {
    Text = "If I have the chance, I would like to invite you to my lab as a guest."
  },
  AvgCommunicate_70494_Content_15 = {
    Text = "A Keeper who can link countless Awakeners... The secrets about you intrigue me greatly."
  },
  AvgCommunicate_70494_Content_16 = {
    Text = "If you and everyone in the Sculptors' Association turn yourselves in to Mythag, cooperation might be worth considering."
  },
  AvgCommunicate_70494_Content_17 = {
    Text = "Heh... I thought I would be scolded fiercely."
  },
  AvgCommunicate_70494_Content_18 = {
    Text = "You are more interesting than I imagined."
  },
  AvgCommunicate_70494_Content_19 = {
    Text = "The days ahead are long, and in the future, we will have many opportunities to communicate."
  },
  AvgCommunicate_70494_Content_2 = {
    Text = "It's you... Herbert Rosenthal..."
  },
  AvgCommunicate_70494_Content_20 = {
    Text = "Please look forward to it, %player%."
  },
  AvgCommunicate_70494_Content_3 = {
    Text = "Oh, it seems someone has already introduced me to you."
  },
  AvgCommunicate_70494_Content_4 = {
    Text = "It actually saved me a lot of trouble."
  },
  AvgCommunicate_70494_Content_5 = {
    Text = "Silver Communications require a bidirectional link. How did you contact me?"
  },
  AvgCommunicate_70494_Content_6 = {Text = "Hmm..."},
  AvgCommunicate_70494_Content_7 = {
    Text = "For those fortunate enough to participate in the development, the Silver communication technology holds no secrets."
  },
  AvgCommunicate_70494_Content_8 = {
    Text = "Are you the developer of Silver Communication?"
  },
  AvgCommunicate_70494_Content_9 = {
    Text = "Old tales can be discussed at leisure when we have time."
  },
  AvgCommunicate_70494_Option_13 = {
    Text = "What exactly do you intend to do?"
  },
  AvgCommunicate_70494_Option_16 = {
    Text = "Unless you turn yourself in."
  },
  AvgCommunicate_70494_Option_2 = {
    Text = "Herbert Rosenthal..."
  },
  AvgCommunicate_70494_Option_5 = {
    Text = "How did you get in touch with me?"
  },
  AvgCommunicate_70495_Content_1 = {
    Text = "Anderson's remains have been destroyed by members of the Sculptors' Association, making it impossible to piece together a complete human figure."
  },
  AvgCommunicate_70495_Content_10 = {
    Text = "Perhaps, one day we will..."
  },
  AvgCommunicate_70495_Content_11 = {
    Text = "Will you be afraid, William?"
  },
  AvgCommunicate_70495_Content_12 = {Text = "..."},
  AvgCommunicate_70495_Content_13 = {
    Text = "Perhaps some people can look past life and death, but not me."
  },
  AvgCommunicate_70495_Content_14 = {
    Text = "I am afraid all the time, %player%."
  },
  AvgCommunicate_70495_Content_15 = {
    Text = "But I have never seen any trace of fear in you."
  },
  AvgCommunicate_70495_Content_16 = {
    Text = "Because I have no time. Because the Dissolution is right before me."
  },
  AvgCommunicate_70495_Content_17 = {
    Text = "Many have perished, yet I still live."
  },
  AvgCommunicate_70495_Content_18 = {
    Text = "Whether it is fear or remembrance, an Investigator of Mythag has no right to stop for this."
  },
  AvgCommunicate_70495_Content_19 = {Text = "..."},
  AvgCommunicate_70495_Content_2 = {
    Text = "Those forcibly extracted Silvers have also been almost completely destroyed."
  },
  AvgCommunicate_70495_Content_20 = {
    Text = "A new task has arrived."
  },
  AvgCommunicate_70495_Content_21 = {
    Text = "We will survive, %player%. Until the day the Dissolution is resolved."
  },
  AvgCommunicate_70495_Content_3 = {
    Text = "We searched the laboratory in the workhouse and only found this."
  },
  AvgCommunicate_70495_Content_4 = {
    Text = "Silver Key, ID L-1463, belonging to Investigator Anderson—it once belonged to him."
  },
  AvgCommunicate_70495_Content_5 = {
    Text = "What will the school do with this Silver Key...?"
  },
  AvgCommunicate_70495_Content_6 = {
    Text = "Recycle it, place it into the Black Pool for remaking, and then distribute it to new Investigators at the next year's Keygrave Ceremony."
  },
  AvgCommunicate_70495_Content_7 = {
    Text = "It will accompany the new Investigator, constantly heading to the most dangerous places."
  },
  AvgCommunicate_70495_Content_8 = {
    Text = "Until that Investigator resigns or dies."
  },
  AvgCommunicate_70495_Content_9 = {
    Text = "Perhaps, one day we will..."
  },
  AvgCommunicate_70495_Option_10 = {
    Text = "Will you be afraid?"
  },
  AvgCommunicate_70495_Option_15 = {
    Text = "I have never felt your fear."
  },
  AvgCommunicate_70495_Option_5 = {
    Text = "What will the school do with this Silver Key...?"
  },
  AvgCommunicate_70495_Option_9 = {
    Text = "Will we end up like Anderson?"
  },
  AvgCommunicate_70496_Content_1 = {
    Text = "The ritual of these Aram people... is truly shocking."
  },
  AvgCommunicate_70496_Content_10 = {
    Text = "Am I that kind of person?"
  },
  AvgCommunicate_70496_Content_11 = {
    Text = "I was just asking casually, why are you so tense?"
  },
  AvgCommunicate_70496_Content_12 = {
    Text = "Acting like that will make you an open book at the card table. Your mental fortitude needs improvement, {Male=Mr.,Female=Miss} Keeper."
  },
  AvgCommunicate_70496_Content_13 = {
    Text = "In short, the secrets of this desert are likely far more complex than we anticipated."
  },
  AvgCommunicate_70496_Content_14 = {
    Text = "The subsequent investigation requires extra caution."
  },
  AvgCommunicate_70496_Content_2 = {
    Text = "I thought you would accept that Aram woman's invitation."
  },
  AvgCommunicate_70496_Content_3 = {Text = "..."},
  AvgCommunicate_70496_Content_4 = {
    Text = "What kind of image do I truly have in your heart..."
  },
  AvgCommunicate_70496_Content_5 = {
    Text = "I never expected that Ryker, who is usually so charming, would also have things he couldn't accept."
  },
  AvgCommunicate_70496_Content_6 = {
    Text = "There are no stories with flowers and wine, only the most primitive and wildest desires."
  },
  AvgCommunicate_70496_Content_7 = {
    Text = "This kind of ritual is indeed not to my liking."
  },
  AvgCommunicate_70496_Content_8 = {
    Text = "Speaking of which, you didn't accept any strange invitations, did you?"
  },
  AvgCommunicate_70496_Content_9 = {
    Text = "Wh- of course not... how could I possibly!"
  },
  AvgCommunicate_70496_Option_2 = {
    Text = "I thought you would accept that Aram woman's invitation."
  },
  AvgCommunicate_70496_Option_5 = {
    Text = "I didn't expect that there would be things you couldn't accept either."
  },
  AvgCommunicate_70496_Option_9 = {
    Text = "Wh- of course not... how could I possibly!"
  },
  AvgCommunicate_70497_Content_1 = {
    Text = "Hello, {Male=Mr.,Female=Miss} Keeper."
  },
  AvgCommunicate_70497_Content_2 = {
    Text = "Did you have fun playing with Juliette's toys?"
  },
  AvgCommunicate_70497_Content_3 = {
    Text = "Are you... the mole?!"
  },
  AvgCommunicate_70497_Content_4 = {
    Text = "I thought you would have figured out who I am sooner. What a pity."
  },
  AvgCommunicate_70497_Content_5 = {
    Text = "But it's alright; it's just the final game after all."
  },
  AvgCommunicate_70497_Content_6 = {
    Text = "Now, the game is about to end."
  },
  AvgCommunicate_70497_Content_7 = {
    Text = "Before the destined destruction arrives, I am curious about only one thing."
  },
  AvgCommunicate_70497_Content_8 = {
    Text = "Can the eternal truth of Chaos—the bold Keeper we shamelessly speak of, Mythag's brave Savior—truly face it with courage?"
  },
  AvgCommunicate_70497_Option_3 = {
    Text = "Are you... the mole?!"
  },
  AvgCommunicate_70498_Content_1 = {
    Text = "I am not a foolish merchant, but upon careful consideration, it seems I've made a losing deal..."
  },
  AvgCommunicate_70498_Content_10 = {
    Text = "Always being wary of lies is a basic quality of a qualified businesswoman."
  },
  AvgCommunicate_70498_Content_11 = {
    Text = "So... is that really the true face of Lady Daffodil?"
  },
  AvgCommunicate_70498_Content_12 = {
    Text = "There is no cost more expensive than reality, little {Male=Mr.,Female=Miss} Keeper."
  },
  AvgCommunicate_70498_Content_13 = {
    Text = "Thank you, Lady Daffodil."
  },
  AvgCommunicate_70498_Content_14 = {
    Text = "What I just said was a joke. I know what it means for someone like you to reveal your true self."
  },
  AvgCommunicate_70498_Content_15 = {
    Text = "This is a precious gift, and I will cherish it well."
  },
  AvgCommunicate_70498_Content_16 = {
    Text = "Don't think you can brush me off with just a few words, little one."
  },
  AvgCommunicate_70498_Content_17 = {
    Text = "In return, shouldn't you also give me a gift?"
  },
  AvgCommunicate_70498_Content_18 = {
    Text = "Have I been seen through...?"
  },
  AvgCommunicate_70498_Content_19 = {
    Text = "Lady Daffodil, what would you like?"
  },
  AvgCommunicate_70498_Content_2 = {Text = "?"},
  AvgCommunicate_70498_Content_20 = {
    Text = "Since you've already seen my true form, when will you be ready to show me your true self?"
  },
  AvgCommunicate_70498_Content_21 = {
    Text = "My true self? What does that mean... I don't quite understand, Lady Daffodil."
  },
  AvgCommunicate_70498_Content_22 = {
    Text = "It seems that Mythag hasn't told you anything yet..."
  },
  AvgCommunicate_70498_Content_23 = {
    Text = "The time has not yet come. No worries."
  },
  AvgCommunicate_70498_Content_24 = {
    Text = "Remember our deal today, little one."
  },
  AvgCommunicate_70498_Content_25 = {
    Text = "I'm looking forward to the day you reveal your true form."
  },
  AvgCommunicate_70498_Content_3 = {
    Text = "Haven't you already obtained the head you desired?"
  },
  AvgCommunicate_70498_Content_4 = {
    Text = "That vibrant sea of gray matter has become yet another cherished piece in your collection."
  },
  AvgCommunicate_70498_Content_5 = {
    Text = "Indeed, that was a beautiful head; this trade cannot be considered a total loss."
  },
  AvgCommunicate_70498_Content_6 = {
    Text = "However, the cost I've paid is still a bit too high."
  },
  AvgCommunicate_70498_Content_7 = {
    Text = "You only gave me a glimpse of your true form..."
  },
  AvgCommunicate_70498_Content_8 = {
    Text = "And whether that's really how you look, it's hard to say."
  },
  AvgCommunicate_70498_Content_9 = {
    Text = "Heh heh... Not bad, little one."
  },
  AvgCommunicate_70498_Option_11 = {
    Text = "So... is that really the true face of Lady Daffodil?"
  },
  AvgCommunicate_70498_Option_13 = {
    Text = "Thank you, Lady Daffodil."
  },
  AvgCommunicate_70498_Option_18 = {
    Text = "Have I been seen through...?"
  },
  AvgCommunicate_70498_Option_2 = {
    Text = "Haven't you already obtained the head?"
  },
  AvgCommunicate_70498_Option_21 = {
    Text = "My true self? What does that mean..."
  },
  AvgCommunicate_70498_Option_7 = {
    Text = "I just caught a glimpse of your true form..."
  },
  AvgCommunicate_70499_Content_1 = {
    Text = "Eliminating dissenters, she has freed herself from the constraints of Longbel and the Contract. Without these hindrances, in just a few weeks, she has become the fiercest hunter in Londinium's business world."
  },
  AvgCommunicate_70499_Content_10 = {
    Text = "Don't worry, Professor Dexter. We won't let you do such dangerous things next time... I mean, we'll try not to."
  },
  AvgCommunicate_70499_Content_11 = {
    Text = "The existence hidden within Sorel's consciousness seems to be called \"N\". Do you know anything about him?"
  },
  AvgCommunicate_70499_Content_12 = {
    Text = "Not very clear. Sounds like either a scammer or a madman, most likely both."
  },
  AvgCommunicate_70499_Content_13 = {
    Text = "But no matter how heinous, at least this guy has taste. You can tell from his singing."
  },
  AvgCommunicate_70499_Content_14 = {
    Text = "Next time there's an opportunity, we must get to know each other better. Perhaps we can even share a drink or two."
  },
  AvgCommunicate_70499_Content_15 = {
    Text = "...Of course, in a safe environment. My old bones can no longer endure any fright."
  },
  AvgCommunicate_70499_Content_2 = {
    Text = "I think it won't be long before the entire land of Londinium bears her surname."
  },
  AvgCommunicate_70499_Content_3 = {
    Text = "Lady Sorel, what a fascinating person. Fortunately, Mythag is on her side."
  },
  AvgCommunicate_70499_Content_4 = {
    Text = "I owe this matter to your help, Professor Dexter."
  },
  AvgCommunicate_70499_Content_5 = {
    Text = "Thank you for helping to draw out the suspect; otherwise, it would have taken much longer to resolve this matter."
  },
  AvgCommunicate_70499_Content_6 = {
    Text = "I'm simply fulfilling the duties of a gentleman."
  },
  AvgCommunicate_70499_Content_7 = {
    Text = "It was a proposal put forward by Ramona. As her father, how could I refuse?"
  },
  AvgCommunicate_70499_Content_8 = {
    Text = "However, if something like this happens again next time, I hope you can act a bit faster."
  },
  AvgCommunicate_70499_Content_9 = {
    Text = "Don't wait until that fellow's knife is just five centimeters from my neck to show up; it's really frightening."
  },
  AvgCommunicate_70499_Option_10 = {
    Text = "There won't be a next time... I'll do my best."
  },
  AvgCommunicate_70499_Option_11 = {
    Text = "Do you know about \"N\"?"
  },
  AvgCommunicate_70499_Option_4 = {
    Text = "Thank you for helping to lure out the suspect."
  },
  AvgCommunicate_70500_Content_1 = {
    Text = "The conversation at the café was quite enjoyable, {Male=Mr.,Female=Miss} Keeper."
  },
  AvgCommunicate_70500_Content_10 = {
    Text = "If this situation happens again, and you need to shoot the real me to get everyone else out, would you do it?"
  },
  AvgCommunicate_70500_Content_11 = {
    Text = "Hmm... of course."
  },
  AvgCommunicate_70500_Content_12 = {
    Text = "Rest assured, {Male=Mr.,Female=Miss} Keeper. Fortune will still smile upon me."
  },
  AvgCommunicate_70500_Content_13 = {
    Text = "At that moment, my gun would definitely have no bullets."
  },
  AvgCommunicate_70500_Content_14 = {Text = "70% no."},
  AvgCommunicate_70500_Content_2 = {
    Text = "It was an honor to witness the making of a gambler."
  },
  AvgCommunicate_70500_Content_3 = {
    Text = "My favorite part is when the gambler lost everything and had his soul stolen."
  },
  AvgCommunicate_70500_Content_4 = {
    Text = "Ha... there are victories and defeats; that's life."
  },
  AvgCommunicate_70500_Content_5 = {
    Text = "See? We've already won back a round this time."
  },
  AvgCommunicate_70500_Content_6 = {
    Text = "So, was that shot you fired at me also a gamble?"
  },
  AvgCommunicate_70500_Content_7 = {
    Text = "How could that be? I was a full 70% certain of my judgment."
  },
  AvgCommunicate_70500_Content_8 = {
    Text = "What about the remaining 30%?"
  },
  AvgCommunicate_70500_Content_9 = {
    Text = "There is no remaining 30%. 70% is 100%."
  },
  AvgCommunicate_70500_Option_2 = {
    Text = "It was an honor to witness the making of a gambler."
  },
  AvgCommunicate_70500_Option_6 = {
    Text = "So, was that shot you fired at me also a gamble?"
  },
  AvgCommunicate_70500_Option_8 = {
    Text = "What about the remaining 30%?"
  },
  AvgCommunicate_70501_Content_1 = {
    Text = "Is it good-looking?"
  },
  AvgCommunicate_70501_Content_10 = {
    Text = "However... the story narrated by that set of sculptures is a bit too cruel."
  },
  AvgCommunicate_70501_Content_11 = {
    Text = "You have understood it, Keeper..."
  },
  AvgCommunicate_70501_Content_12 = {
    Text = "All creation is cruel."
  },
  AvgCommunicate_70501_Content_13 = {
    Text = "It is through this cruelty that the static art gains vibrant life."
  },
  AvgCommunicate_70501_Content_14 = {
    Text = "If it were me, I would find this creative process quite exhausting..."
  },
  AvgCommunicate_70501_Content_15 = {
    Text = "But you are different, Sanga. I understand your choice."
  },
  AvgCommunicate_70501_Content_16 = {
    Text = "Works like \"Death of Ms. Coral\" represent the meaning you pursue."
  },
  AvgCommunicate_70501_Content_17 = {
    Text = "I look forward to the \"cruelty\" blooming again in the lines you carve."
  },
  AvgCommunicate_70501_Content_18 = {Text = "..."},
  AvgCommunicate_70501_Content_19 = {
    Text = "I thought you would suggest making my art more \"normal\", like those mundane individuals."
  },
  AvgCommunicate_70501_Content_2 = {
    Text = "What... about your face?"
  },
  AvgCommunicate_70501_Content_20 = {
    Text = "These words mean a lot to me... Thank you, {Male=Mr.,Female=Miss} Keeper."
  },
  AvgCommunicate_70501_Content_21 = {
    Text = "In return, let me tell you a small secret: when you enter a dream, I am standing right beside you."
  },
  AvgCommunicate_70501_Content_22 = {
    Text = "I've captured your flustered expressions. Vividly realistic."
  },
  AvgCommunicate_70501_Content_23 = {
    Text = "When you have time, come visit my little exhibition hall~"
  },
  AvgCommunicate_70501_Content_24 = {
    Text = "Sanga! I'll give you fifty Florins, so please throw away those Sculptures..."
  },
  AvgCommunicate_70501_Content_25 = {
    Text = "What you said is vivid and \"cruel\" art, isn't it, Keeper?"
  },
  AvgCommunicate_70501_Content_3 = {
    Text = "Of course, it's the Sculpture you saw in your dream."
  },
  AvgCommunicate_70501_Content_4 = {
    Text = "The lines of the body are naturally harmonious, but lack the stillness and eternal beauty, as well as theme and creativity, making it difficult to compare with sculptural works."
  },
  AvgCommunicate_70501_Content_5 = {
    Text = "That set of sculptures is rarely seen these days. I would like to know your thoughts on them..."
  },
  AvgCommunicate_70501_Content_6 = {
    Text = "What... your sculpture?"
  },
  AvgCommunicate_70501_Content_7 = {
    Text = "Of course. That group of sculptures is rarely seen by anyone now, and I want to know your opinion..."
  },
  AvgCommunicate_70501_Content_8 = {
    Text = "That was the most beautiful set of sculptures I have ever seen."
  },
  AvgCommunicate_70501_Content_9 = {
    Text = "Though clearly static, the lines depict a dynamism and vitality that living creatures lack."
  },
  AvgCommunicate_70501_Option_14 = {
    Text = "I understand your choice"
  },
  AvgCommunicate_70501_Option_2 = {Text = "Your face?"},
  AvgCommunicate_70501_Option_24 = {Text = "No!!!"},
  AvgCommunicate_70501_Option_6 = {
    Text = "Your sculpture?"
  },
  AvgCommunicate_70501_Option_8 = {
    Text = "Beauty... and cruelty."
  },
  AvgCommunicate_70502_Content_1 = {
    Text = "Boring. Boring, boring!"
  },
  AvgCommunicate_70502_Content_10 = {
    Text = "As you've reminded me many times, slaves aren't allowed in Londinium. This barbaric land..."
  },
  AvgCommunicate_70502_Content_11 = {
    Text = "I have no choice but to listen to you and command them in the Maze."
  },
  AvgCommunicate_70502_Content_12 = {
    Text = "The way they fight in the arena is exactly how I remember it!"
  },
  AvgCommunicate_70502_Content_13 = {
    Text = "So that's what the Maze is used for..."
  },
  AvgCommunicate_70502_Content_14 = {
    Text = "That's right, that's right! It's really exciting!"
  },
  AvgCommunicate_70502_Content_15 = {
    Text = "Come on, let's go watch! This is the ultimate honor I can grant you!"
  },
  AvgCommunicate_70502_Content_16 = {
    Text = "Sure, why not? Learning more about history would be nice..."
  },
  AvgCommunicate_70502_Content_17 = {
    Text = "Uvhash would probably really like your arena. Why not invite him as well?"
  },
  AvgCommunicate_70502_Content_18 = {
    Text = "No way! Keep that devil away from me!!!"
  },
  AvgCommunicate_70502_Content_2 = {
    Text = "Being stuck in this godforsaken place every day is driving me up the wall!"
  },
  AvgCommunicate_70502_Content_3 = {
    Text = "I have rebuilt my Maze! An entire arena constructed according to my memories!"
  },
  AvgCommunicate_70502_Content_4 = {
    Text = "Let's go have fun! Right now!"
  },
  AvgCommunicate_70502_Content_5 = {
    Text = "Will you ever be able to ask instead of order...?"
  },
  AvgCommunicate_70502_Content_6 = {
    Text = "Hmph, why would I bother changing my manner of speaking?"
  },
  AvgCommunicate_70502_Content_7 = {
    Text = "I've already made ten thousand concessions! The only people I get to order around are the slaves in my maze!"
  },
  AvgCommunicate_70502_Content_8 = {
    Text = "So you're alright with everything now?"
  },
  AvgCommunicate_70502_Content_9 = {
    Text = "Of course. What's there to be afraid of?"
  },
  AvgCommunicate_70502_Option_16 = {
    Text = "Then I'll bring Uvhash along."
  },
  AvgCommunicate_70502_Option_5 = {
    Text = "Will you ever be able to ask instead of order...?"
  },
  AvgCommunicate_70502_Option_8 = {
    Text = "So you're alright with everything now?"
  },
  AvgCommunicate_70503_Content_1 = {
    Text = "The incident that occurred in the church... If you hadn't been there, more innocent people would have been harmed..."
  },
  AvgCommunicate_70503_Content_10 = {
    Text = "But now, she is the current head of the Church of the Lightbearers."
  },
  AvgCommunicate_70503_Content_11 = {
    Text = "What?! The leader of the Church of the Lightbearers?!!"
  },
  AvgCommunicate_70503_Content_12 = {
    Text = "But that's the greatest enemy of your church... How could your student have become..."
  },
  AvgCommunicate_70503_Content_13 = {
    Text = "A lengthy tale, Messenger."
  },
  AvgCommunicate_70503_Content_14 = {
    Text = "She once worked alongside me for the All-Father's cause, dedicating all we had to the All-Father's people."
  },
  AvgCommunicate_70503_Content_15 = {
    Text = "But, as you can see, it is not so easy for the wayward to turn from the All-Father. Those atrocities and prejudices cannot be dispelled with just some Blessings."
  },
  AvgCommunicate_70503_Content_16 = {
    Text = "Because of the tribulations I endured, she embarked on a divergent path from which it would be difficult to return."
  },
  AvgCommunicate_70503_Content_17 = {
    Text = "So that's how it is..."
  },
  AvgCommunicate_70503_Content_18 = {
    Text = "I understand. Just like what happened before in the church, those who did not change because of your good deeds caused her to change..."
  },
  AvgCommunicate_70503_Content_19 = {
    Text = "The All-Father once taught us that matters in this world are not always black and white. Good deeds can sometimes also be a mistake."
  },
  AvgCommunicate_70503_Content_2 = {
    Text = "On behalf of the Chantry of Life and the innocent survivors, I express my heartfelt gratitude to you, Pale Messenger."
  },
  AvgCommunicate_70503_Content_20 = {
    Text = "I dedicated everything to the victims, but I forgot that my student was also a victim herself."
  },
  AvgCommunicate_70503_Content_21 = {
    Text = "The church and my beliefs may have saved many people, but they failed to save her."
  },
  AvgCommunicate_70503_Content_22 = {
    Text = "I was not a qualified teacher, Pale Messenger."
  },
  AvgCommunicate_70503_Content_23 = {
    Text = "I will continue to walk the path of the All-Father. But I wonder if I will ever have the chance to make up for this regret concerning that student..."
  },
  AvgCommunicate_70503_Content_3 = {
    Text = "You're welcome, Bishop Salvador. It's all part of my duty."
  },
  AvgCommunicate_70503_Content_4 = {
    Text = "Bishop, regarding your past, there is a question I would like to ask you..."
  },
  AvgCommunicate_70503_Content_5 = {
    Text = "Ask freely, Messenger."
  },
  AvgCommunicate_70503_Content_6 = {
    Text = "My past will be open to every person under the All-Father's protection."
  },
  AvgCommunicate_70503_Content_7 = {
    Text = "When I linked with you, aside from Sophia, I saw a woman having a conversation with you."
  },
  AvgCommunicate_70503_Content_8 = {
    Text = "That memory takes up a large portion of your Spirit... Were you familiar with each other?"
  },
  AvgCommunicate_70503_Content_9 = {
    Text = "Indeed, very familiar. She was once my most outstanding student."
  },
