  },
  AvgCommunicate_70513_Content_1 = {
    Text = "Regarding the sound of the flute you heard while you were unconscious, I went to investigate it."
  },
  AvgCommunicate_70513_Content_10 = {
    Text = "I don't know whether to praise your optimism or criticize your ignorance."
  },
  AvgCommunicate_70513_Content_11 = {
    Text = "What Tawil specifically mentions is usually a catastrophe."
  },
  AvgCommunicate_70513_Content_12 = {
    Text = "The worst kind."
  },
  AvgCommunicate_70513_Content_13 = {
    Text = "Since it has already happened... let's just take a moment to self-comfort."
  },
  AvgCommunicate_70513_Content_14 = {
    Text = "In short, I will continue to investigate this matter."
  },
  AvgCommunicate_70513_Content_15 = {
    Text = "It currently has no substantial effect on you, so there's no need to worry about it for now."
  },
  AvgCommunicate_70513_Content_16 = {
    Text = "First, let's deal with the trouble at hand."
  },
  AvgCommunicate_70513_Content_2 = {
    Text = "Is there any result?"
  },
  AvgCommunicate_70513_Content_3 = {
    Text = "Little. But there was some findings."
  },
  AvgCommunicate_70513_Content_4 = {
    Text = "Is it my imagination?"
  },
  AvgCommunicate_70513_Content_5 = {
    Text = "It can be clearly stated: No."
  },
  AvgCommunicate_70513_Content_6 = {
    Text = "I consulted Professor Alistair."
  },
  AvgCommunicate_70513_Content_7 = {
    Text = "Although there is currently no record of this flute sound, Tawil once mentioned something about it to him."
  },
  AvgCommunicate_70513_Content_8 = {Text = "Tawil?!"},
  AvgCommunicate_70513_Content_9 = {
    Text = "Just a dream, and it's already involving a figure of that caliber..."
  },
  AvgCommunicate_70513_Option_13 = {
    Text = "Just consider it a form of self-comfort."
  },
  AvgCommunicate_70513_Option_2 = {
    Text = "Is there any result?"
  },
  AvgCommunicate_70513_Option_4 = {
    Text = "Is it my imagination?"
  },
  AvgCommunicate_70513_Option_8 = {Text = "Tawil?!"},
  AvgCommunicate_70514_Content_1 = {
    Text = "{Male=Mr.,Female=Miss} Keeper, the publisher has sent me a letter."
  },
  AvgCommunicate_70514_Content_10 = {
    Text = "It was under her protection that I was able to wander carefree in the world of flowers and poetry."
  },
  AvgCommunicate_70514_Content_11 = {
    Text = "All of those things—the protection and the harm—are now in the past..."
  },
  AvgCommunicate_70514_Content_12 = {
    Text = "{Male=Mr.,Female=Miss} Keeper, thank you for taking me to Cité this time... This journey was very important to me."
  },
  AvgCommunicate_70514_Content_13 = {
    Text = "That's right. Everything from your past with Colette is now behind you."
  },
  AvgCommunicate_70514_Content_14 = {
    Text = "Look ahead, Horla."
  },
  AvgCommunicate_70514_Content_15 = {
    Text = "Okay, {Male=Mr.,Female=Miss} Keeper."
  },
  AvgCommunicate_70514_Content_16 = {
    Text = "This poetry collection is my farewell to the past."
  },
  AvgCommunicate_70514_Content_17 = {
    Text = "I will remember Colette in her youth. I will remember Colette in her old age. And now, I will let her go..."
  },
  AvgCommunicate_70514_Content_18 = {
    Text = "There is a new life, and new poems, awaiting me."
  },
  AvgCommunicate_70514_Content_2 = {
    Text = "They congratulated me—this collection has achieved excellent results."
  },
  AvgCommunicate_70514_Content_3 = {
    Text = "Congratulations, Horla!"
  },
  AvgCommunicate_70514_Content_4 = {
    Text = "Thank you, {Male=Mr.,Female=Miss} Keeper."
  },
  AvgCommunicate_70514_Content_5 = {
    Text = "In the past, Colette was in charge of all these matters."
  },
  AvgCommunicate_70514_Content_6 = {
    Text = "All along, it has been her shouldering this part."
  },
  AvgCommunicate_70514_Content_7 = {
    Text = "In my experience, this is the first time I've ever seen you show concern for sales."
  },
  AvgCommunicate_70514_Content_8 = {
    Text = "Because the author of this poetry collection is Horla Corlet..."
  },
  AvgCommunicate_70514_Content_9 = {
    Text = "Colette would care. She has been the one bearing this responsibility all along."
  },
  AvgCommunicate_70514_Option_13 = {
    Text = "Look ahead."
  },
  AvgCommunicate_70514_Option_3 = {
    Text = "Congratulations!"
  },
  AvgCommunicate_70514_Option_7 = {
    Text = "First time I've seen you care about sales."
  },
  AvgCommunicate_70515_Content_1 = {
    Text = "I just took a look around the wax museum... It's really a mess."
  },
  AvgCommunicate_70515_Content_10 = {
    Text = "To avoid those mad dogs from the Committee, I haven't played my game for a long time..."
  },
  AvgCommunicate_70515_Content_11 = {
    Text = "You could consider surrendering in Mythag together with Rogers."
  },
  AvgCommunicate_70515_Content_12 = {
    Text = "You should know the consequences of being caught by the Committee."
  },
  AvgCommunicate_70515_Content_13 = {
    Text = "Your mouth sure knows how to deceive, sweetheart."
  },
  AvgCommunicate_70515_Content_14 = {
    Text = "However, I had a great time playing with you all in the wax museum."
  },
  AvgCommunicate_70515_Content_15 = {
    Text = "Maybe I will give it some serious thought."
  },
  AvgCommunicate_70515_Content_16 = {
    Text = "Perhaps there will be another day of meeting. I'm looking forward to it, {Male=Mr.,Female=Miss} Keeper~"
  },
  AvgCommunicate_70515_Content_2 = {
    Text = "You really don't know how to cherish things!"
  },
  AvgCommunicate_70515_Content_3 = {Text = "Pandia?"},
  AvgCommunicate_70515_Content_4 = {
    Text = "Where have you and Rogers gone?"
  },
  AvgCommunicate_70515_Content_5 = {
    Text = "What, are you thinking about someone's whip?"
  },
  AvgCommunicate_70515_Content_6 = {
    Text = "You have committed so many crimes; I just want to arrest you and bring you to justice."
  },
  AvgCommunicate_70515_Content_7 = {
    Text = "Those who lost their lives because of the wax museum must get justice."
  },
  AvgCommunicate_70515_Content_8 = {
    Text = "Oh dear, those were all the works of Lord Rogers; I certainly don't have that artistic talent."
  },
  AvgCommunicate_70515_Content_9 = {
    Text = "What a pity, what a pity. The hand of Lord Rogers, born for art, is gone."
  },
  AvgCommunicate_70515_Option_11 = {
    Text = "Perhaps you can choose to come to Mythag."
  },
  AvgCommunicate_70515_Option_3 = {Text = "Pandia?"},
  AvgCommunicate_70515_Option_6 = {
    Text = "I want... I want to arrest you and bring you to justice."
  },
  AvgCommunicate_70516_Content_1 = {
    Text = "%player%..."
  },
  AvgCommunicate_70516_Content_10 = {
    Text = "Make sure to stay safe, Ramona!"
  },
  AvgCommunicate_70516_Content_11 = {
    Text = "Do you have so little confidence in your partner?"
  },
  AvgCommunicate_70516_Content_12 = {
    Text = "Don't worry, I'll join you after I've taken care of things over here."
  },
  AvgCommunicate_70516_Content_13 = {
    Text = "Your situation is the most perilous right now; you must be careful, %player%..."
  },
  AvgCommunicate_70516_Content_2 = {
    Text = "Ramona?! Are you alright?"
  },
  AvgCommunicate_70516_Content_3 = {
    Text = "I'm alright."
  },
  AvgCommunicate_70516_Content_4 = {
    Text = "I just ran into a few Committee agents and have already dealt with them."
  },
  AvgCommunicate_70516_Content_5 = {
    Text = "I wanted to come over and join you, but I saw a group of agents heading towards the teaching building..."
  },
  AvgCommunicate_70516_Content_6 = {
    Text = "Many teachers and students are in class there; I'm worried that they might do them harm."
  },
  AvgCommunicate_70516_Content_7 = {
    Text = "I need to escort them to a safe place."
  },
  AvgCommunicate_70516_Content_8 = {
    Text = "I just confronted Clementine; I'll take care of things here."
  },
  AvgCommunicate_70516_Content_9 = {
    Text = "I'll leave the teaching building to you."
  },
  AvgCommunicate_70516_Option_2 = {
    Text = "Ramona?! Are you alright?"
  },
  AvgCommunicate_70516_Option_8 = {
    Text = "Take care of yourself, Ramona!"
  },
  AvgCommunicate_70517_Content_1 = {
    Text = "Desolate. Pedantic. Lacking the passion that life should have..."
  },
  AvgCommunicate_70517_Content_10 = {
    Text = "You, just like back then, still care so much about the rules."
  },
  AvgCommunicate_70517_Content_11 = {
    Text = "It's fine; I've already rented the school hall."
  },
  AvgCommunicate_70517_Content_12 = {
    Text = "Renting the hall? Why?"
  },
  AvgCommunicate_70517_Content_13 = {
    Text = "Because the Mythag school board refused to let me purchase it."
  },
  AvgCommunicate_70517_Content_14 = {
    Text = "It seems you've misunderstood my question..."
  },
  AvgCommunicate_70517_Content_15 = {
    Text = "It doesn't matter. Tomorrow night, I will host a banquet in the hall."
  },
  AvgCommunicate_70517_Content_16 = {
    Text = "A passionate, novel, and truly vibrant banquet, brimming with the vitality of life—just like those in my castle."
  },
  AvgCommunicate_70517_Content_17 = {
    Text = "The necessary preparations and props are now fully ready."
  },
  AvgCommunicate_70517_Content_18 = {
    Text = "I have already circumvented the obstacles posed by the rules in advance. No one will disturb us."
  },
  AvgCommunicate_70517_Content_19 = {
    Text = "I trust you can find the way there, {Male=Mr.,Female=Miss} Keeper?"
  },
  AvgCommunicate_70517_Content_2 = {
    Text = "What are you talking about..."
  },
  AvgCommunicate_70517_Content_3 = {
    Text = "I mean, we haven't held a proper banquet for a long time."
  },
  AvgCommunicate_70517_Content_4 = {
    Text = "Wasn't there a dinner gathering in the hall last weekend?"
  },
  AvgCommunicate_70517_Content_5 = {
    Text = "A group of well-dressed individuals sitting together, maintaining a polite social distance, behaving courteously, yet always careful to conceal the sordid thoughts in their hearts..."
  },
  AvgCommunicate_70517_Content_6 = {
    Text = "This exhausting social activity cannot be called a banquet."
  },
  AvgCommunicate_70517_Content_7 = {
    Text = "You've already seen the true banquet in my castle, haven't you?"
  },
  AvgCommunicate_70517_Content_8 = {
    Text = "Madam Wanda, after all, this is Londinium, not your castle..."
  },
  AvgCommunicate_70517_Content_9 = {
    Text = "Some of the most basic rules are still ones we must abide by..."
  },
  AvgCommunicate_70517_Option_12 = {Text = "Hmm? Why?"},
  AvgCommunicate_70517_Option_14 = {
    Text = "It seems you've misunderstood my question..."
  },
  AvgCommunicate_70517_Option_2 = {
    Text = "What are you talking about..."
  },
  AvgCommunicate_70517_Option_4 = {
    Text = "Wasn't there a dinner gathering in the hall last weekend?"
  },
  AvgCommunicate_70517_Option_8 = {
    Text = "After all, this is Londinium, not your castle..."
  },
  AvgCommunicate_70518_Content_1 = {
    Text = "Hey, where has Miryam gone?"
  },
  AvgCommunicate_70518_Content_10 = {
    Text = "Ambitious... I like that title."
  },
  AvgCommunicate_70518_Content_11 = {
    Text = "Don't worry. I've already made adjustments to the plan."
  },
  AvgCommunicate_70518_Content_12 = {
    Text = "The resurgence of the Philistines is not limited to seizing the power of the Seafarer."
  },
  AvgCommunicate_70518_Content_13 = {
    Text = "I'm looking for her because I want to discuss the next step in our collaboration."
  },
  AvgCommunicate_70518_Content_14 = {
    Text = "The resources and power that Mythag possesses are of great use to both her and me."
  },
  AvgCommunicate_70518_Content_15 = {
    Text = "Plotting against Mythag right in front of me... isn't that a bit inappropriate?"
  },
  AvgCommunicate_70518_Content_16 = {
    Text = "It's cooperation. After all, if the powers of the Seafarer and Philistine can be utilized, your investigation will proceed much smoother, won't it?"
  },
  AvgCommunicate_70518_Content_17 = {
    Text = "It sounds like... there might be some truth to that..."
  },
  AvgCommunicate_70518_Content_18 = {
    Text = "Very good, very quick to catch on, {Male=Mr.,Female=Miss} Keeper."
  },
  AvgCommunicate_70518_Content_19 = {
    Text = "Don't worry, once the mission is complete, you will receive everything that is due to you."
  },
  AvgCommunicate_70518_Content_2 = {
    Text = "Goliath, what are you trying to do?!"
  },
  AvgCommunicate_70518_Content_20 = {
    Text = "After all... you're the little one who followed me in the dream."
  },
  AvgCommunicate_70518_Content_21 = {
    Text = "I, Goliath, never treats those who follow me poorly."
  },
  AvgCommunicate_70518_Content_3 = {
    Text = "I know about your issues with Miryam. Calm down, this is not the time for fighting!"
  },
  AvgCommunicate_70518_Content_4 = {Text = "..."},
  AvgCommunicate_70518_Content_5 = {
    Text = "Am I just a brute who only knows how to fight to you?"
  },
  AvgCommunicate_70518_Content_6 = {
    Text = "Are you not? Is there any other possibility?"
  },
  AvgCommunicate_70518_Content_7 = {
    Text = "So Mythag's {Male=Mr.,Female=Miss} Keeper lacks even this bit of judgment. This place is doomed."
  },
  AvgCommunicate_70518_Content_8 = {
    Text = "I know that an ambitious person like you is no reckless fool."
  },
  AvgCommunicate_70518_Content_9 = {
    Text = "But just in case, I wanted to remind you first."
  },
  AvgCommunicate_70518_Option_15 = {
    Text = "Plotting against us in front of me? Isn't that inappropriate?"
  },
  AvgCommunicate_70518_Option_17 = {
    Text = "It sounds quite reasonable..."
  },
  AvgCommunicate_70518_Option_2 = {
    Text = "What are you trying to do?!"
  },
  AvgCommunicate_70518_Option_6 = {
    Text = "Are you not?"
  },
  AvgCommunicate_70518_Option_8 = {
    Text = "Of course not!"
  },
  AvgCommunicate_70519_Content_1 = {
    Text = "The boxing ring. Come and take a look."
  },
  AvgCommunicate_70519_Content_10 = {
    Text = "The boxing arena, with sunlight, cake, chains, blood, and sand."
  },
  AvgCommunicate_70519_Content_11 = {Text = "It's me."},
  AvgCommunicate_70519_Content_2 = {
    Text = "Here we go again... I wonder if you're here to beat someone up or drink blood..."
  },
  AvgCommunicate_70519_Content_3 = {
    Text = "In Remouahe, you didn't get enough hits on that guide, did you?"
  },
  AvgCommunicate_70519_Content_4 = {Text = "?!"},
  AvgCommunicate_70519_Content_5 = {
    Text = "It was you all along..."
  },
  AvgCommunicate_70519_Content_6 = {Text = "Ha."},
  AvgCommunicate_70519_Content_7 = {
    Text = "That battle is worth commemorating."
  },
  AvgCommunicate_70519_Content_8 = {
    Text = "The boxing ring awaits! Let's go!"
  },
  AvgCommunicate_70519_Content_9 = {
    Text = "I just want to talk to you about what you've experienced before... I don't mean to start a fight with you!"
  },
  AvgCommunicate_70519_Option_2 = {
    Text = "It has started again..."
  },
  AvgCommunicate_70519_Option_3 = {
    Text = "Didn't get enough hits in Remouahe, did you?"
  },
  AvgCommunicate_70519_Option_9 = {
    Text = "I have no intention of fighting you!"
  },
  AvgCommunicate_70520_Content_1 = {Text = "Meow~"},
  AvgCommunicate_70520_Content_10 = {
    Text = "I've gained weight and my sleep has gotten worse because of her!"
  },
  AvgCommunicate_70520_Content_11 = {
    Text = "Maybe Clown 24? She's always telling jokes and brings joy everywhere she goes..."
  },
  AvgCommunicate_70520_Content_12 = {
    Text = "What's there to like about a crass jester desperate for even an ounce of attention?"
  },
  AvgCommunicate_70520_Content_13 = {
    Text = "If you want to see a clown that badly, go visit the circus. Or better yet, look in the mirror."
  },
  AvgCommunicate_70520_Content_14 = {
    Text = "Cat 24 is so adorable!"
  },
  AvgCommunicate_70520_Content_15 = {
    Text = "What's there to like about a beast that can't even speak the human language?"
  },
  AvgCommunicate_70520_Content_16 = {
    Text = "Are you that desperate to fill the void of your empty life that you want a glorified pet?"
  },
  AvgCommunicate_70520_Content_17 = {
    Text = "It seems I'm speaking with Toxic 24."
  },
  AvgCommunicate_70520_Content_18 = {
    Text = "Toxic 24?! I'm the Dignified 24!!"
  },
  AvgCommunicate_70520_Content_19 = {Text = "..."},
  AvgCommunicate_70520_Content_2 = {
    Text = "24, your personality switched again..."
  },
  AvgCommunicate_70520_Content_20 = {
    Text = "I'm... I'm sorry, Keeper!"
  },
  AvgCommunicate_70520_Content_21 = {
    Text = "Recently, I went to the slums with Jenkin. After hearing the people there trash talk so much, my newly formed personality decided to imitate their manner of speech..."
  },
  AvgCommunicate_70520_Content_22 = {
    Text = "Please rest assured, Keeper! I'll make sure to teach this personality some manners!"
  },
  AvgCommunicate_70520_Content_23 = {
    Text = "Do your best..."
  },
  AvgCommunicate_70520_Content_3 = {
    Text = "So which \"24\" am I talking to now?"
  },
  AvgCommunicate_70520_Content_4 = {
    Text = "You don't need to worry about that."
  },
  AvgCommunicate_70520_Content_5 = {
    Text = "Instead, tell me which personality is your favorite."
  },
  AvgCommunicate_70520_Content_6 = {
    Text = "Uh, let me think..."
  },
  AvgCommunicate_70520_Content_7 = {
    Text = "Maybe Scholar 24? She looks very smart and has a very cute mustache..."
  },
  AvgCommunicate_70520_Content_8 = {
    Text = "Tsk. That one only knows how to read boring books every day."
  },
  AvgCommunicate_70520_Content_9 = {
    Text = "Never going out, wasting her time thinking about useless things."
  },
  AvgCommunicate_70520_Option_11 = {Text = "Clown 24"},
  AvgCommunicate_70520_Option_14 = {Text = "Cat 24"},
  AvgCommunicate_70520_Option_17 = {
    Text = "It seems I'm speaking with Toxic 24."
  },
  AvgCommunicate_70520_Option_2 = {Text = "..."},
  AvgCommunicate_70520_Option_23 = {
    Text = "Do your best..."
  },
  AvgCommunicate_70520_Option_7 = {Text = "Scholar 24"},
  AvgCommunicate_70521_Content_1 = {
    Text = "Thank you, Master..."
  },
  AvgCommunicate_70521_Content_10 = {
    Text = "The finished film—would you like to go see it together?"
  },
  AvgCommunicate_70521_Content_11 = {Text = "Really?!"},
  AvgCommunicate_70521_Content_12 = {
    Text = "Thank you, Master!"
  },
  AvgCommunicate_70521_Content_2 = {
    Text = "Hmm? What is it?"
  },
  AvgCommunicate_70521_Content_3 = {
    Text = "I understood the story that was filmed..."
  },
  AvgCommunicate_70521_Content_4 = {
    Text = "You made it for me... Thank you..."
  },
  AvgCommunicate_70521_Content_5 = {
    Text = "Then, did you like it?"
  },
  AvgCommunicate_70521_Content_6 = {Text = "Yes!"},
  AvgCommunicate_70521_Content_7 = {
    Text = "I like the ending of that story."
  },
  AvgCommunicate_70521_Content_8 = {
    Text = "The girl lived happily ever after with her mother..."
  },
  AvgCommunicate_70521_Content_9 = {
    Text = "I heard from Lady Daffodil that the film has been processed."
  },
  AvgCommunicate_70521_Option_2 = {
    Text = "Hmm? What is it?"
  },
  AvgCommunicate_70521_Option_5 = {
    Text = "Then, did you like it?"
  },
  AvgCommunicate_70521_Option_9 = {
    Text = "The film is complete. Would you like to go watch it together?"
  },
  AvgCommunicate_70522_Content_1 = {
    Text = "Several land consolidations within Londinium are proceeding smoothly, and those troublesome contracts have been resolved."
  },
  AvgCommunicate_70522_Content_10 = {
    Text = "What? The {Male=Mr.,Female=Miss} Keeper of Mythag, could you possibly be a person who breaks their word?"
  },
  AvgCommunicate_70522_Content_11 = {
    Text = "Certainly not! It's just..."
  },
  AvgCommunicate_70522_Content_12 = {
    Text = "Heh... How childish of you. Though I can't see it, I bet your face must be flushed down to your neck right now while thinking about how to lie, correct?"
  },
  AvgCommunicate_70522_Content_13 = {
    Text = "Here's the deal. The item I promised to give to Mythag needs to be handed over by you. Is that reason sufficient?"
  },
  AvgCommunicate_70522_Content_14 = {Text = "But..."},
  AvgCommunicate_70522_Content_15 = {
    Text = "Alright, no more \"buts\"; it's decided."
  },
  AvgCommunicate_70522_Content_16 = {
    Text = "Alright, I promise you... It's my honor, Lady Sorel."
  },
  AvgCommunicate_70522_Content_17 = {
    Text = "That's better."
  },
  AvgCommunicate_70522_Content_18 = {
    Text = "Between us, there's no need for those formalities and mutual probing anymore."
  },
  AvgCommunicate_70522_Content_19 = {
    Text = "At 8 PM tonight, in the wine cellar of my manor. No one will stop you."
  },
  AvgCommunicate_70522_Content_2 = {
    Text = "All of this is thanks to your help, {Male=Mr.,Female=Miss} Keeper."
  },
  AvgCommunicate_70522_Content_20 = {
    Text = "I'm waiting for you, my little knight."
  },
  AvgCommunicate_70522_Content_3 = {
    Text = "Those tedious business salons are finally coming to an end."
  },
  AvgCommunicate_70522_Content_4 = {
    Text = "While you have some free time, come over and have a drink with me?"
  },
  AvgCommunicate_70522_Content_5 = {
    Text = "Mythag students are prohibited from drinking..."
  },
  AvgCommunicate_70522_Content_6 = {
    Text = "Is that so? Professor Dexter didn't say that to me."
  },
  AvgCommunicate_70522_Content_7 = {
    Text = "Who made this rule? It needs to be changed."
  },
  AvgCommunicate_70522_Content_8 = {
    Text = "Ah, this..."
  },
  AvgCommunicate_70522_Content_9 = {
    Text = "You still owe me a drink. Remember?"
  },
  AvgCommunicate_70522_Option_11 = {
    Text = "Certainly not! It's just..."
  },
  AvgCommunicate_70522_Option_16 = {
    Text = "It is my honor, Lady Sorel."
  },
  AvgCommunicate_70522_Option_5 = {
    Text = "Mythag students are prohibited from drinking..."
  },
  AvgCommunicate_70523_Content_1 = {
    Text = "In the rush, I didn't have the chance to introduce the local customs and culture to all of you."
  },
  AvgCommunicate_70523_Content_10 = {
    Text = "As I mentioned before, I am but a messenger proclaiming the teachings of my Lord."
  },
  AvgCommunicate_70523_Content_11 = {
    Text = "Our God will create a better future for the world."
  },
  AvgCommunicate_70523_Content_12 = {
    Text = "Primitive groups like the Aram are also part of this future and remain our most loyal friends."
  },
  AvgCommunicate_70523_Content_13 = {
    Text = "Of course, I also understand {Male=Mr.,Female=Miss} Keeper's doubts."
  },
  AvgCommunicate_70523_Content_14 = {
    Text = "I believe that as long as we spend a little more time together, these doubts will naturally disappear."
  },
  AvgCommunicate_70523_Content_15 = {
    Text = "You have traveled a long way; please rest well."
  },
  AvgCommunicate_70523_Content_16 = {
    Text = "On behalf of Remouahe, I sincerely welcome your arrival, {Male=Mr.,Female=Miss} Keeper."
  },
  AvgCommunicate_70523_Content_2 = {
    Text = "I wonder if {Male=Mr.,Female=Miss} Keeper has any questions for me?"
  },
  AvgCommunicate_70523_Content_3 = {
    Text = "I'm a bit curious about the customs here."
  },
  AvgCommunicate_70523_Content_4 = {
    Text = "Although the Aramite people have lived by herding for generations, away from industrial society, please do not regard them as uncivilized barbaric tribes."
  },
  AvgCommunicate_70523_Content_5 = {
