  AvgCommunicate_80100_Option_9 = {Text = "..."},
  AvgCommunicate_80101_Content_1 = {
    Text = "I heard you've been feeling down lately. If you don't mind, you can come to me for a consultation."
  },
  AvgCommunicate_80101_Content_10 = {
    Text = "Ah~, just describing it makes my silver heart tremble non-stop..."
  },
  AvgCommunicate_80101_Content_11 = {
    Text = "%player%, I can't wait to delve into your heart and taste your memories."
  },
  AvgCommunicate_80101_Content_12 = {
    Text = "Then you'll be dissappointed, since I've already left."
  },
  AvgCommunicate_80101_Content_13 = {
    Text = "I know. One of my patients already let me know."
  },
  AvgCommunicate_80101_Content_14 = {
    Text = "She was even thoughtful enough to send me your location, so..."
  },
  AvgCommunicate_80101_Content_15 = {
    Text = "I will be there shortly."
  },
  AvgCommunicate_80101_Content_2 = {
    Text = "You don't need to act tough, Keeper. A professional can help relieve your stress more quickly."
  },
  AvgCommunicate_80101_Content_3 = {
    Text = "How did you know...?"
  },
  AvgCommunicate_80101_Content_4 = {Text = "Secret~"},
  AvgCommunicate_80101_Content_5 = {
    Text = "So, what's your answer?"
  },
  AvgCommunicate_80101_Content_6 = {
    Text = "I promise I won't do anything else this time."
  },
  AvgCommunicate_80101_Content_7 = {
    Text = "You said the same last time... and the time before that..."
  },
  AvgCommunicate_80101_Content_8 = {
    Text = "It's not my fault; rather, your conciousness that's filled with such pleasant memories..."
  },
  AvgCommunicate_80101_Content_9 = {
    Text = "Those memories that far exceed the pain that an ordinary person can endure, bearing the aura of that great existence, the most supreme sweetness..."
  },
  AvgCommunicate_80101_Option_12 = {
    Text = "...Then you'll be disappointed."
  },
  AvgCommunicate_80101_Option_3 = {
    Text = "How did you know...?"
  },
  AvgCommunicate_80101_Option_7 = {
    Text = "You said the same last time... and the time before that..."
  },
  AvgCommunicate_80102_Content_1 = {
    Text = "%player%, if you don't mind, could I take care of your psychological needs?"
  },
  AvgCommunicate_80102_Content_10 = {
    Text = "But I won't do anything extreme. Trust me."
  },
  AvgCommunicate_80102_Content_11 = {Text = "...Really?"},
  AvgCommunicate_80102_Content_12 = {
    Text = "Of course. After all, I'm only a psychologist."
  },
  AvgCommunicate_80102_Content_2 = {
    Text = "I think you need a personal psychiatrist."
  },
  AvgCommunicate_80102_Content_3 = {
    Text = "...I feel like this is unnecessary."
  },
  AvgCommunicate_80102_Content_4 = {
    Text = "No, as the only Keeper, your existence itself is worth valuing."
  },
  AvgCommunicate_80102_Content_5 = {
    Text = "I just want to use my professional skills to help you."
  },
  AvgCommunicate_80102_Content_6 = {
    Text = "Is that right? Why do I feel like you have ulterior motives..."
  },
  AvgCommunicate_80102_Content_7 = {
    Text = "For example, using the guise of a personal psychologist to peer into my memories?"
  },
  AvgCommunicate_80102_Content_8 = {
    Text = "Oh dear, was it that obvious? Oh well, nothing I can do about that."
  },
  AvgCommunicate_80102_Content_9 = {
    Text = "I am indeed very, very interested in your memories, especially after you spoke about that world."
  },
  AvgCommunicate_80102_Option_11 = {Text = "...Really?"},
  AvgCommunicate_80102_Option_3 = {
    Text = "...I feel like this is unnecessary."
  },
  AvgCommunicate_80102_Option_6 = {
    Text = "...Is that right?"
  },
  AvgCommunicate_80104_Content_1 = {
    Text = "Thank you for sending me that report."
  },
  AvgCommunicate_80104_Content_10 = {
    Text = "As for whether it's possible to return to that world, relying solely on the power of Doll: Inferno and I is clearly not enough."
  },
  AvgCommunicate_80104_Content_11 = {
    Text = "So you need my power...? I understand."
  },
  AvgCommunicate_80104_Content_12 = {
    Text = "I'll accept this gift. In return, I'll give you a free psychological consultation."
  },
  AvgCommunicate_80104_Content_13 = {
    Text = "%player%, when do you have free time?"
  },
  AvgCommunicate_80104_Content_14 = {
    Text = "Whether as a doctor or as a friend, I feel responsible for deeply understanding your inner self."
  },
  AvgCommunicate_80104_Content_15 = {
    Text = "I'm on field duty... signal poor... will continue later..."
  },
  AvgCommunicate_80104_Content_16 = {Text = "%player%?"},
  AvgCommunicate_80104_Content_17 = {Text = "%player%?"},
  AvgCommunicate_80104_Content_18 = {
    Text = "Heh, I know you're still there. But it's okay, we still have plenty of time."
  },
  AvgCommunicate_80104_Content_2 = {
