  AvgCommunicate_81323_Content_1 = {
    Text = "My benefactor, when will you hand me a new workbook?"
  },
  AvgCommunicate_81323_Content_10 = {
    Text = "I understand. In that case, are there any other teachers you can recommend for me?"
  },
  AvgCommunicate_81323_Content_11 = {
    Text = "If there aren't any, I can self study and do my best by myself."
  },
  AvgCommunicate_81323_Content_12 = {
    Text = "There is, but... she's not exactly the most stable..."
  },
  AvgCommunicate_81323_Content_13 = {
    Text = "It's okay. I'm not afraid."
  },
  AvgCommunicate_81323_Content_14 = {
    Text = "I'm the one that's scared! Well, if I go find Winkle... mmm, she'd probably go mad first."
  },
  AvgCommunicate_81323_Content_15 = {
    Text = "Mad? Does this Master Winkle have some sort of illness?"
  },
  AvgCommunicate_81323_Content_16 = {
    Text = "Well no... well, I can't say there ISN'T but... Ah, never mind! Let me first teach you a core fundamental truth of learning!"
  },
  AvgCommunicate_81323_Content_17 = {
    Text = "Alright, benefactor, I'm all ears."
  },
  AvgCommunicate_81323_Content_18 = {
    Text = "Simply put... don't question literally everything!!!"
  },
  AvgCommunicate_81323_Content_19 = {
    Text = "How could that be, benefactor? I don't understand... if I don't ask enough questions, how can I truly learn a subject..?"
  },
  AvgCommunicate_81323_Content_2 = {
    Text = "And regarding the last two books, I have read them thoroughly and made a total of 107 notes of questions; I hope you can provide me some guidance in your spare time."
  },
  AvgCommunicate_81323_Content_20 = {
    Text = "Aren't you tired of all this?! With your go getter attitude, you would surely succeed in anything you set out to do..."
  },
  AvgCommunicate_81323_Content_21 = {
    Text = "Thank you, benefactor. I am truly blessed to have the opportunity to learn about things that interest me."
  },
  AvgCommunicate_81323_Content_22 = {
    Text = "Tired? If I'm tired, I'll just rest for a bit and be fine."
  },
  AvgCommunicate_81323_Content_23 = {
    Text = "So, when can you introduce me to the new teacher? I'll try not to ask too many questions."
  },
  AvgCommunicate_81323_Content_24 = {
    Text = "Um... how about I only ask 97 questions instead?"
  },
  AvgCommunicate_81323_Content_3 = {Text = "I'm sorry."},
  AvgCommunicate_81323_Content_4 = {
    Text = "I'm truly sorry."
  },
  AvgCommunicate_81323_Content_6 = {
    Text = "I shouldn't have given you my homework. One should handle one's own affairs..."
  },
  AvgCommunicate_81323_Content_7 = {
    Text = "Please, don't ask me for more! If this goes on, I'll have nightmares every night!!"
  },
  AvgCommunicate_81323_Content_8 = {
    Text = "Ah...I'm sorry. I didn't realize I was troubling my benefactor so much. I've been too inattentive."
  },
  AvgCommunicate_81323_Content_9 = {
    Text = "Don't apologize, it's not your fault. I don't think I'm suited to be a teacher..."
  },
  AvgCommunicate_81323_Option_12 = {
    Text = "There is, but..."
  },
  AvgCommunicate_81323_Option_14 = {
    Text = "I'm the one that's scared!"
