  },
  AvgCommunicate_81324_Content_1 = {
    Text = "Benefactor, I've been reading and have new questions to ask."
  },
  AvgCommunicate_81324_Content_10 = {
    Text = "So you're saying... it depends on what you were thinking while doing it?"
  },
  AvgCommunicate_81324_Content_11 = {
    Text = "That's right! Think about it. When I asked you to write those two assignments for you, was I exploiting you for free labor, or was I giving you the opportunity to learn something new?"
  },
  AvgCommunicate_81324_Content_12 = {
    Text = "I don't know."
  },
  AvgCommunicate_81324_Content_13 = {
    Text = "What do you mean you don't know?! Of course I did it to teach you!"
  },
  AvgCommunicate_81324_Content_14 = {
    Text = "So that's how it is. It seems I misunderstood; I thought you only wanted me to help you with your homework."
  },
  AvgCommunicate_81324_Content_16 = {
    Text = "Ahaha... Well, let's think about it again. When we perform an action with the goal to help someone, sincerely help someone, that can be considered an ethical action."
  },
  AvgCommunicate_81324_Content_17 = {
    Text = "Treating someone purely as a tool, on the other hand, would certainly be unethical."
  },
  AvgCommunicate_81324_Content_18 = {
    Text = "I think I understand now. It's like how the Lantern used me and Pollux as tools for sacrifice, without considering our feelings. What they did was unethical."
  },
  AvgCommunicate_81324_Content_19 = {
    Text = "That's right, that's right! You understand perfectly!"
  },
  AvgCommunicate_81324_Content_2 = {
    Text = "You said before that homework is used to test and refine one's knowledge. If the knowledge is mastered, you don't need to worry about who actually does it."
  },
  AvgCommunicate_81324_Content_20 = {
    Text = "I understand, benefactor, you are truly an ethical person! Then, please give me a few more assignments. I'll dilligently complete them and come back to consult you!"
  },
  AvgCommunicate_81324_Content_21 = {
    Text = "Benefactor?"
  },
  AvgCommunicate_81324_Content_22 = {
    Text = "Uhh, I suddenly have something to attend to... You should go directly to Doll about the homework!"
  },
  AvgCommunicate_81324_Content_3 = {
    Text = "Um... I may have said something like that before..."
  },
  AvgCommunicate_81324_Content_4 = {
    Text = "But the books I've been reading state that having other people do your work for you is unethical."
  },
  AvgCommunicate_81324_Content_6 = {
    Text = "So how do we determine if this matter is ethical?"
  },
  AvgCommunicate_81324_Content_7 = {
    Text = "Uh... about this matter, you should view it dialectically."
  },
  AvgCommunicate_81324_Content_8 = {
    Text = "We cannot say for certain yes or no."
  },
  AvgCommunicate_81324_Content_9 = {
    Text = "When judging something, you can't only consider the result. You must also consider the purpose behind the action."
  },
  AvgCommunicate_81324_Option_11 = {
    Text = "That's right."
  },
  AvgCommunicate_81324_Option_13 = {
    Text = "What do you mean you don't know?!"
  },
  AvgCommunicate_81324_Option_19 = {
    Text = "That's right, that's right! You understand perfectly!"
