  AvgCommunicate_81325_Content_1 = {
    Text = "What a magical box, benefactor. Is this really not powered by some sort of magic or ritual array?"
  },
  AvgCommunicate_81325_Content_10 = {
    Text = "Not exactly... It's just that these two disciplines are currently advancing, and many scholars will broaden and deepen these studies, creating new knowledge."
  },
  AvgCommunicate_81325_Content_11 = {
    Text = "If you choose such a flourishing field as your learning goal, then of course you'll have to keep learning your whole life."
  },
  AvgCommunicate_81325_Content_12 = {
    Text = "I see. Knowledge that continues to develop... truly magnificent."
  },
  AvgCommunicate_81325_Content_13 = {
    Text = "When we study the scriptures of the lantern, we cannot change a single word; the content must remain constant, repeated, and unchanging forever."
  },
  AvgCommunicate_81325_Content_14 = {
    Text = "But every time I study the scriptures, I feel like I'm trapped in a box... with the end already before me."
  },
  AvgCommunicate_81325_Content_15 = {
    Text = "Indeed, continuing to grow ones knowledge is the true meaning of life!"
  },
  AvgCommunicate_81325_Content_16 = {
    Text = "That's... truly inspiring..."
  },
  AvgCommunicate_81325_Content_17 = {
    Text = "Speaking of which, I have an excellent learning opportunity that I can generously gift you for free."
  },
  AvgCommunicate_81325_Content_18 = {
    Text = "Really, benefactor!? My gratitude is beyond words."
  },
  AvgCommunicate_81325_Content_19 = {
