  AvgCommunicate_81325_Content_20 = {
    Text = "Uh, I mean, which one would you like to learn first?"
  },
  AvgCommunicate_81325_Content_3 = {
    Text = "Ah, what a pity... How did you know I was going to take it apart, benefactor? Did you read my mind?"
  },
  AvgCommunicate_81325_Content_4 = {
    Text = "Not really... I don't even need Psychology to guess your next move!"
  },
  AvgCommunicate_81325_Content_5 = {
    Text = "Psychology must be a very profound subject. Regrettably, my knowledge of this subject is indeed lacking..."
  },
  AvgCommunicate_81325_Content_6 = {
