  AvgCommunicate_84107_Content_1 = {
    Text = "When does this vacation end?"
  },
  AvgCommunicate_84107_Content_10 = {
    Text = "All these factors combined must be weighed to plan the most efficient and rational route."
  },
  AvgCommunicate_84107_Content_11 = {
    Text = "...I see. It seems every job is important."
  },
  AvgCommunicate_84107_Content_12 = {
    Text = "Yes. Since I made the choice, I must take responsibility."
  },
  AvgCommunicate_84107_Content_13 = {
    Text = "From now on, I will patrol every night to ensure that no accidents occur at the academy this break."
  },
  AvgCommunicate_84107_Content_14 = {
    Text = "Keeper, let's stop here for now. I have to get back to work."
  },
  AvgCommunicate_84107_Content_2 = {
