  },
  AvgCommunicate_84107_Content_5 = {
    Text = "The academy map has been updated, the clock has been calibrated, and the flags and flagpoles have been tidied up."
  },
  AvgCommunicate_84107_Content_6 = {
    Text = "I'll continue maintaining these things every day to ensure we can start work at any time."
  },
  AvgCommunicate_84107_Content_7 = {
    Text = "...Does it require that much preparation to organize lunch time?"
  },
  AvgCommunicate_84107_Content_8 = {
    Text = "Of course. Which cafeteria is the most popular, which academy has the most students, and which students want to go to the cafeteria first will all affect the entire route planning."
  },
  AvgCommunicate_84107_Content_9 = {
    Text = "Which flowerbed has the new stray cat taken as its home, which area the students trampled to make a new path, which road needs maintenance..."
  },
  AvgCommunicate_84107_Option_11 = {Text = "...I see."},
  AvgCommunicate_84107_Option_2 = {
    Text = "...Didn't it just begin?"
  },
  AvgCommunicate_84107_Option_7 = {
    Text = "Does it require that much preparation?"
  },
  AvgCommunicate_84108_Content_1 = {
    Text = "Keeper, I am truly sorry for the last incident."
  },
  AvgCommunicate_84108_Content_10 = {
    Text = "But this is not the sea after all, so I made adjustments based on the specific situation."
  },
  AvgCommunicate_84108_Content_11 = {
    Text = "The so-called adjustment won't just tie you and me together, right..."
  },
  AvgCommunicate_84108_Content_12 = {
    Text = "Yes. This way, if I encounter any accidents, you can detect and stop it at the first instance."
  },
  AvgCommunicate_84108_Content_13 = {
    Text = "......Can I refuse?"
  },
  AvgCommunicate_84108_Content_14 = {
    Text = "You can certainly refuse."
  },
  AvgCommunicate_84108_Content_15 = {
    Text = "But I have already reached outside the door."
  },
  AvgCommunicate_84108_Content_2 = {
    Text = "......Are you referring to the insomnia causing the St. Elmo's fire incident?"
  },
  AvgCommunicate_84108_Content_3 = {
    Text = "Even though Doll: Inferno knocked me out in time, I still feel a sense of guilt."
  },
  AvgCommunicate_84108_Content_4 = {
    Text = "I pondered for a long time and felt I needed to be punished."
  },
  AvgCommunicate_84108_Content_5 = {
    Text = "There's no need to do this. The last incident did not cause any serious consequences."
  },
  AvgCommunicate_84108_Content_6 = {
    Text = "No, if you do something wrong, you must be punished. That's the rule."
  },
  AvgCommunicate_84108_Content_7 = {
    Text = "I have handcuffed myself with one side, and the other side needs your cooperation."
  },
  AvgCommunicate_84108_Content_8 = {
    Text = "My cooperation?"
  },
  AvgCommunicate_84108_Content_9 = {
    Text = "Generally, offenders on the ship are shackled at the legs and exposed to the sun on the deck for several hours."
  },
  AvgCommunicate_84108_Option_11 = {
    Text = "The so-called adjustment won't..."
  },
  AvgCommunicate_84108_Option_13 = {
    Text = "......Can I refuse?"
