  AvgCommunicate_84108_Option_2 = {
    Text = "Do you mean..."
  },
  AvgCommunicate_84108_Option_5 = {
    Text = "There's no need to do this."
  },
  AvgCommunicate_84108_Option_8 = {
    Text = "My cooperation?"
  },
  AvgCommunicate_84109_Content_1 = {
    Text = "Keeper, thank you."
  },
  AvgCommunicate_84109_Content_10 = {Text = "..."},
  AvgCommunicate_84109_Content_11 = {
    Text = "Actually..."
  },
  AvgCommunicate_84109_Content_12 = {
    Text = "Actually? Why are you suddenly speaking so hesitantly? That's not like you."
  },
  AvgCommunicate_84109_Content_13 = {
    Text = "Actually, we don't need to visit maritime museums. Just having a moment of \"relaxation\" is fine too."
  },
  AvgCommunicate_84109_Content_14 = {
    Text = "While I can't quite grasp what you mean by normal \"relaxation,\" I do feel a profound sense of calm when I am with you."
  },
  AvgCommunicate_84109_Content_15 = {
    Text = "It feels like being on a peaceful sea—no storms, and no chance of encountering them. I just have to follow the course to reach the destination safely."
  },
  AvgCommunicate_84109_Content_16 = {
    Text = "...Although that metaphor is a bit hard to follow, I think I roughly understand what you mean."
  },
  AvgCommunicate_84109_Content_17 = {
    Text = "In the future, we can explore many different places. The world is vast; there are many beautiful sights beyond the ocean."
  },
  AvgCommunicate_84109_Content_18 = {
    Text = "...I understand. I will try that."
  },
  AvgCommunicate_84109_Content_19 = {
    Text = "I'll go see... the beautiful scenery that is different from the ocean."
  },
  AvgCommunicate_84109_Content_2 = {
    Text = "Why the sudden expression of gratitude?"
  },
  AvgCommunicate_84109_Content_3 = {
    Text = "I learned a great deal on this trip to the London Maritime Museum."
  },
  AvgCommunicate_84109_Content_4 = {
    Text = "The displayed nautical clocks, hand-drawn charts, and fragments of logbooks will all help me improve my navigation skills."
  },
  AvgCommunicate_84109_Content_5 = {
    Text = "I will put all of this to use in the next voyage, ensuring everyone returns safely to the harbor."
  },
  AvgCommunicate_84109_Content_6 = {
    Text = "I recall the purpose of going to the London Maritime Museum that day was supposed to be for \"relaxation\"..."
  },
  AvgCommunicate_84109_Content_7 = {
    Text = "Forget it. As long as you're happy."
  },
  AvgCommunicate_84109_Content_8 = {
    Text = "Yes, I am very happy, and I hope we can often go out to relax together in the future."
  },
  AvgCommunicate_84109_Content_9 = {
    Text = "No problem. I'll check what other maritime museums in London we can visit."
  },
