  },
  AvgCommunicate_84110_Content_12 = {
    Text = "Right here, conducting experiments on the conduction device, testing whether the energy of @2<AvgCommunicateConfuseColor.Light> can be transformed into light energy."
  },
  AvgCommunicate_84110_Content_13 = {
    Text = "Why don't you refuse?"
  },
  AvgCommunicate_84110_Content_14 = {
    Text = "Why refuse? Serving passengers is one of my duties."
  },
  AvgCommunicate_84110_Content_15 = {Text = "..."},
  AvgCommunicate_84110_Content_16 = {
    Text = "I am going over now. You hold Winkle back for me."
  },
  AvgCommunicate_84110_Content_17 = {
    Text = "Understood. I will fulfill your command, even unto death."
  },
  AvgCommunicate_84110_Content_2 = {
    Text = "Winkle took your portion again?"
  },
  AvgCommunicate_84110_Content_3 = {
    Text = "To be precise, it wasn't \"taken,\" but rather I gave it to that passenger."
  },
  AvgCommunicate_84110_Content_4 = {
    Text = "...Again with the reason of \"I'll join the voyage next time\"?"
  },
  AvgCommunicate_84110_Content_5 = {
    Text = "I am just fulfilling my duties. Serving the passengers is also one of my responsibilities."
  },
  AvgCommunicate_84110_Content_6 = {
    Text = "...Supply request has been approved. This is the last time."
  },
  AvgCommunicate_84110_Content_7 = {
    Text = "By the way, is Winkle still trying to extract the @2 from your chest recently?"
  },
  AvgCommunicate_84110_Content_8 = {
    Text = "Not anymore; this passenger has changed their research methods."
  },
  AvgCommunicate_84110_Content_9 = {
    Text = "For example, testing the intensity of @2<AvgCommunicateConfuseColor.Light> with an impact current meter, scanning the spectral lines of @2<AvgCommunicateConfuseColor.Light> with a prism, using a human testing platform to verify the connection of @2<AvgCommunicateConfuseColor.Light> with nerve fibers..."
  },
  AvgCommunicate_84110_Option_10 = {
    Text = "Wait, how could it get more absurd!"
  },
  AvgCommunicate_84110_Option_13 = {
    Text = "Why don't you refuse?"
  },
  AvgCommunicate_84110_Option_15 = {Text = "..."},
  AvgCommunicate_84110_Option_2 = {
    Text = "Winkle took your portion again?"
  },
  AvgCommunicate_84110_Option_4 = {
    Text = "Again, it is because..."
  },
  AvgCommunicate_84110_Option_6 = {
    Text = "Supply request has been approved..."
  },
  AvgCommunicate_94500_Content_1 = {
    Text = "Thanks to your introduction, after meeting Lord Ogier, he has introduced us to even more friends."
  },
  AvgCommunicate_94500_Content_10 = {
    Text = "Lord Ogier also mentioned that a knight's training is even more complex and tedious than this. It seems that, as the stories say, every knight is a truly respectable person."
  },
  AvgCommunicate_94500_Content_11 = {
    Text = "Indeed, Ogier is the most diligent in his training among all the Awakeners!"
  },
  AvgCommunicate_94500_Content_12 = {
    Text = "We also noticed that Instructor Alva, despite having a disability, performs the exact same training as us."
  },
  AvgCommunicate_94500_Content_13 = {
    Text = "We originally thought Instructor Alva was also a knight, but she said she used to be a soldier. I don't know what kind of profession a soldier is, but it must be as respectable as a knight."
  },
  AvgCommunicate_94500_Content_14 = {
    Text = "Soldiers are people who fight for their country, so you could consider them a type of knight. However, compared to the strict moral code of knights, a soldier's actions don't always represent justice."
  },
  AvgCommunicate_94500_Content_15 = {
    Text = "Alva only realized this after leaving the army. Perhaps the life she has now is more peaceful for her."
  },
  AvgCommunicate_94500_Content_16 = {
    Text = "I understand. You mean that a knight represents not power, but a spirit of justice. Just people like Instructor Alva and even you, all possess the soul of a knight."
  },
  AvgCommunicate_94500_Content_18 = {
    Text = "While that was very nicely said, why does it make me so embarrassed...?"
  },
  AvgCommunicate_94500_Content_2 = {
    Text = "That's wonderful news! I'm genuinely happy for you."
  },
  AvgCommunicate_94500_Content_3 = {
    Text = "We have already met many Awakeners, and indeed, as you said, most of them are friendly people."
  },
  AvgCommunicate_94500_Content_4 = {
    Text = "I feel quite ashamed when I think back to how cautious and suspicious I was of others when I first arrived here."
  },
  AvgCommunicate_94500_Content_5 = {
    Text = "Actually, that's fine. After all, there are still quite a few people you should be cautious of..."
  },
  AvgCommunicate_94500_Content_6 = {
    Text = "Castor and I are now attending Instructor Alva's training course, along with Lord Ogier."
  },
  AvgCommunicate_94500_Content_7 = {
    Text = "Lord Ogier's fighting posture is truly dazzling, but he himself seems unaccustomed to receiving praise. What a humble person."
  },
  AvgCommunicate_94500_Content_8 = {
    Text = "Ha ha, Ogier is just easily shy. Just talk to him normally."
  },
  AvgCommunicate_94500_Content_9 = {
    Text = "I see. Castor and I never received combat training at the church; such heavy exercise is genuinely strenuous. Yet, Lord Ogier says he does this every day. What incredible perseverance."
  },
  AvgCommunicate_94500_Option_11 = {
    Text = "Indeed, Ogier is the most diligent in his training among all the Awakeners!"
  },
  AvgCommunicate_94500_Option_14 = {
    Text = "I suppose so..."
  },
  AvgCommunicate_94500_Option_2 = {
    Text = "That's wonderful news! I'm genuinely happy for you."
  },
  AvgCommunicate_94500_Option_5 = {
    Text = "Actually, that's fine. After all, there are still quite a few people you should be cautious of..."
  },
  AvgCommunicate_94500_Option_8 = {
    Text = "Ogier is just easily shy."
  },
  AvgCommunicate_94501_Content_1 = {
    Text = "Esteemed Benefactor, thank you for painstakingly preparing this dwelling for Castor and me."
  },
  AvgCommunicate_94501_Content_10 = {
    Text = "Castor was so taken with it that he was washing his face five times a day, but after I intervened, it's down to three."
  },
  AvgCommunicate_94501_Content_12 = {
    Text = "Washing your face too many times will damage your skin!"
  },
  AvgCommunicate_94501_Content_13 = {
    Text = "But wait, you hadn't used these things before? I didn't realize the Church of the Lightbearers was so austere."
  },
  AvgCommunicate_94501_Content_14 = {
    Text = "We hadn't, indeed, but it's not due to the church's austerity. As the Twin Divi, we were always required to restrain our desires and focus on our spiritual practice."
  },
  AvgCommunicate_94501_Content_15 = {
    Text = "We've had virtually no contact with these kinds of technology products. Our daily routines and meals were governed by many strict rules."
  },
  AvgCommunicate_94501_Content_16 = {
    Text = "Though our clothes and meals were generally luxurious, we couldn't eat outside of mealtimes, and we were required to leave the chamber as soon as it was time to wake up."
  },
  AvgCommunicate_94501_Content_17 = {
    Text = "As a child, I often dreamt of a day when I wouldn't have to wake up early and could eat whatever I wanted all day long."
  },
  AvgCommunicate_94501_Content_18 = {
    Text = "These past few days, I've repeatedly seen a young girl carrying food passing through the corridor in the afternoon. It seems the life I dreamt of is already routine here."
  },
  AvgCommunicate_94501_Content_19 = {
    Text = "Ah, that would likely be Murphy going to fetch her little cakes... Your past life truly sounds exhausting."
  },
  AvgCommunicate_94501_Content_2 = {
    Text = "When Castor mentioned a bed had been specially added to the house, I knew instantly it was your thoughtful gesture."
  },
  AvgCommunicate_94501_Content_20 = {
    Text = "Everything is behind us now. Those errors and distortions will remain in the past. We will embark on the correct path with a new beginning, which we ask you to witness."
  },
  AvgCommunicate_94501_Content_21 = {
    Text = "You are too kind. If you have any questions, just let me know. Your attitude alone makes you countless times more reassuring than some other Awakeners!"
  },
  AvgCommunicate_94501_Content_3 = {
    Text = "We grew up accustomed to sharing a chamber in the church palace, and we were quite anxious when we heard the rule here was one room per person."
  },
  AvgCommunicate_94501_Content_4 = {
    Text = "Seeing you consider our needs with such meticulous care now, I truly realize how correct Lady Thais was to suggest we seek refuge with you."
  },
  AvgCommunicate_94501_Content_5 = {
    Text = "Haha, it's nothing, really. Are you both settling in comfortably since you arrived?"
  },
  AvgCommunicate_94501_Content_6 = {
    Text = "Thanks to your care, everything is fine. While the quarters here are as small as a maid's room, they are fully furnished, and after adapting, they feel quite warm and cozy."
  },
  AvgCommunicate_94501_Content_7 = {
    Text = "Ahaha, is that so? Well, that's good, that's good..."
  },
  AvgCommunicate_94501_Content_8 = {
    Text = "We have slowly learned to live without being served; please don't worry about us. In fact, this is something we've both dreamed of for years."
  },
  AvgCommunicate_94501_Content_9 = {
    Text = "The facial cleanser provided in the room is truly wondrous—using it as instructed produces many cloud-like bubbles. And the taste of the toothpaste is so fresh!"
  },
  AvgCommunicate_94501_Option_19 = {
    Text = "Ah, that would likely be Murphy going to fetch her little cakes..."
  },
  AvgCommunicate_94501_Option_21 = {
    Text = "You are too kind."
  },
  AvgCommunicate_94501_Option_5 = {
    Text = "Oh, it was nothing at all."
  },
  AvgCommunicate_94501_Option_7 = {
    Text = "Ahaha, is that so? Well, that's good, that's good..."
  },
  AvgCommunicate_94502_Content_1 = {
    Text = "I apologize for intruding, but might I request a small favor for an introduction?"
  },
  AvgCommunicate_94502_Content_10 = {
    Text = "Oh! That must be Ogier and Lotan."
  },
  AvgCommunicate_94502_Content_11 = {
    Text = "Ogier... I've noted the name. That young man's demeanor was so honorable and heroic, it truly captured our hearts. Castor and I wanted to approach, but they quickly passed by and left."
  },
  AvgCommunicate_94502_Content_12 = {
    Text = "After returning to the dormitory, we couldn't stop thinking about that knight, yet we didn't know how to initiate contact. So, we came to ask for your introduction, hoping you can spare the time and effort to facilitate our meeting."
  },
  AvgCommunicate_94502_Content_13 = {
    Text = "I understand. Honestly, you don't need to be so formal. Ogier is a very kind person. If you simply ask him, he would be delighted to be your friend."
  },
  AvgCommunicate_94502_Content_14 = {
    Text = "Truly admirable for a real knight—such broad-mindedness is commendable, willing to accept those like us who were once enemies."
  },
  AvgCommunicate_94502_Content_15 = {
    Text = "No, no, that has nothing to do with being magnanimous! That's just how normal people make friends!"
  },
  AvgCommunicate_94502_Content_16 = {
    Text = "Although not every Awakener is a normal person... most people here are quite friendly. You should just interact with them freely and normally."
  },
  AvgCommunicate_94502_Content_17 = {
    Text = "I apologize. Could you please enlighten me: what exactly is... normal communication?"
  },
  AvgCommunicate_94502_Content_19 = {
    Text = "I understand. Let me tell you the secret to making friends!"
  },
  AvgCommunicate_94502_Content_2 = {
    Text = "Ever since you suggested we try to make more friends, Castor and I have often lingered in the busier areas."
  },
  AvgCommunicate_94502_Content_20 = {
    Text = "It is initiative! Sincerity and initiative are what truly connect with people!"
  },
  AvgCommunicate_94502_Content_21 = {
    Text = "Remember, you might be rejected or deceived, but that is the fault of the people who hurt you. Never doubt that sincerity is the right approach."
  },
  AvgCommunicate_94502_Content_22 = {
    Text = "Develop a resilient heart, and then bravely go out and experience friendship!"
  },
  AvgCommunicate_94502_Content_23 = {
    Text = "Your wisdom always inspires my utmost reverence and admiration. I will truly internalize your teachings. Thank you sincerely, my guiding light."
  },
  AvgCommunicate_94502_Content_3 = {Text = "Lingered?"},
  AvgCommunicate_94502_Content_4 = {
    Text = "Yes. We often sit quietly in the restaurant or the square, observing the passing people, trying not to disturb anyone."
  },
  AvgCommunicate_94502_Content_6 = {
    Text = "Uh, while your intentions are good, you won't make friends just by sitting there!"
  },
  AvgCommunicate_94502_Content_7 = {
    Text = "Is that so? We were so constrained by our former strictures. But I didn't expect there to be a real knight here!"
  },
  AvgCommunicate_94502_Content_8 = {
    Text = "You may have heard from Castor that we both deeply admire the stories of knights."
  },
  AvgCommunicate_94502_Content_9 = {
    Text = "That day in the square, we saw a young man holding a long spear, discussing the knight's spear technique with a lady."
  },
  AvgCommunicate_94502_Option_10 = {
    Text = "Oh! That must be Ogier and Lotan."
  },
  AvgCommunicate_94502_Option_13 = {
    Text = "Honestly, you don't need to be so formal."
  },
  AvgCommunicate_94502_Option_15 = {
    Text = "That has nothing to do with broad-mindedness!"
  },
  AvgCommunicate_94502_Option_3 = {Text = "Lingered?"},
  AvgCommunicate_95003_Content_1 = {
    Text = "Hey, little one, got a minute?"
  },
  AvgCommunicate_95003_Content_10 = {
    Text = "\"...When the stars align, the Divine Fetus will be born from Her womb.\""
  },
  AvgCommunicate_95003_Content_11 = {
    Text = "\"...Although we no longer perform any rituals or sacrifices, I hope this information can provide some inspiration for you.\""
  },
  AvgCommunicate_95003_Content_12 = {
    Text = "\"...If you have time, I would like to discuss our Young King and Savior with you...\""
  },
  AvgCommunicate_95003_Content_13 = {
    Text = "...I know who it is now."
  },
  AvgCommunicate_95003_Content_14 = {
    Text = "...I should have thought of that."
  },
  AvgCommunicate_95003_Content_15 = {
    Text = "So, you know the person, little one?"
  },
  AvgCommunicate_95003_Content_16 = {
    Text = "That's right... leave it to me to handle."
  },
  AvgCommunicate_95003_Content_17 = {
    Text = "The next time you see a letter like this, please make sure not to reply, and inform me immediately!"
  },
  AvgCommunicate_95003_Content_2 = {
    Text = "Is something the matter?"
  },
  AvgCommunicate_95003_Content_3 = {
    Text = "I didn't expect that after our little exchange, some letters actually arrived."
  },
  AvgCommunicate_95003_Content_4 = {
    Text = "Filtering out the ones that are obviously fake, there were surprisingly a few genuine ones among them."
  },
  AvgCommunicate_95003_Content_5 = {
    Text = "I can't believe people actually fell for it!"
  },
  AvgCommunicate_95003_Content_6 = {
    Text = "However, one letter is rather strange; the sender's location is inside Mythag itself."
  },
  AvgCommunicate_95003_Content_7 = {
    Text = "What! We need to notify the Security Office immediately!"
  },
  AvgCommunicate_95003_Content_8 = {
    Text = "Don't panic. To be safe, let me tell you the key points first."
  },
  AvgCommunicate_95003_Content_9 = {
    Text = "\"...Previously, we would select suitable infants to bear the responsibilities of the Divine Mother.\""
  },
  AvgCommunicate_95003_Option_13 = {
    Text = "...I know who it is now."
  },
  AvgCommunicate_95003_Option_14 = {
    Text = "...I should have thought of that."
  },
  AvgCommunicate_95004_Content_1 = {
    Text = "Long time no see, my little Keeper."
  },
  AvgCommunicate_95004_Content_10 = {
    Text = "Of course, something like this is very strange!!!"
  },
  AvgCommunicate_95004_Content_11 = {
    Text = "Haha, just as I suspected."
  },
  AvgCommunicate_95004_Content_12 = {
    Text = "Wh-what did you suspect?"
  },
  AvgCommunicate_95004_Content_13 = {
    Text = "I bet Ismael that the little one would definitely be shocked to see that message."
  },
  AvgCommunicate_95004_Content_14 = {
    Text = "It seems I have won."
  },
  AvgCommunicate_95004_Content_15 = {
    Text = "...Can you tell me who wrote that message?"
  },
  AvgCommunicate_95004_Content_16 = {
    Text = "Although I am capable of writing something similar."
  },
  AvgCommunicate_95004_Content_17 = {
    Text = "That passage was indeed written by Ismael, at my request."
  },
  AvgCommunicate_95004_Content_18 = {
    Text = "...Wonderful. It seems both of you are the culprits."
  },
  AvgCommunicate_95004_Content_19 = {Text = "Uh, ah..."},
  AvgCommunicate_95004_Content_2 = {
    Text = "It has been a while since we last met. I trust your health is good."
  },
  AvgCommunicate_95004_Content_20 = {
    Text = "Little one?"
  },
  AvgCommunicate_95004_Content_21 = {
    Text = "Little one? Are you still there?"
  },
  AvgCommunicate_95004_Content_22 = {
    Text = "I'm not here. You can leave me a voice mail instead."
  },
  AvgCommunicate_95004_Content_23 = {
    Text = "Sorry, sorry, little one. Don't be angry."
  },
  AvgCommunicate_95004_Content_24 = {
    Text = "As compensation, all the spoils from this hunt will be given to you as a gift."
  },
  AvgCommunicate_95004_Content_25 = {
    Text = "Hurry and come! It's been too long; everyone misses you terribly."
  },
  AvgCommunicate_95004_Content_26 = {
    Text = "...Hmph, fine. For the sake of the gift, I'll forgive you this time!"
  },
  AvgCommunicate_95004_Content_27 = {
    Text = "I'll be right over. But there won't be a next time!"
  },
  AvgCommunicate_95004_Content_28 = {
    Text = "(Then I suppose I'll use a different method to tease the little one.)"
  },
  AvgCommunicate_95004_Content_29 = {
    Text = "I saw that! There won't be a next time!"
  },
  AvgCommunicate_95004_Content_3 = {
    Text = "If you are free today, I would like to invite you to participate in this grand hunt."
  },
  AvgCommunicate_95004_Content_4 = {
    Text = "We have prepared an excellent position for you; everyone awaits your arrival."
  },
  AvgCommunicate_95004_Content_5 = {
    Text = "K-Kathigu-Ra? Are you Kathigu-Ra???"
  },
  AvgCommunicate_95004_Content_6 = {
    Text = "Of course, the one speaking to you is Kathigu-Ra, The Living Flame Who Never Forgets."
  },
  AvgCommunicate_95004_Content_7 = {
    Text = "Kathigu-Ra, be normal! You're scaring me!"
  },
  AvgCommunicate_95004_Content_8 = {
    Text = "Is there something strange about my manner of speaking?"
  },
  AvgCommunicate_95004_Content_9 = {
    Text = "It's very strange!!"
  },
  AvgCommunicate_95004_Option_10 = {
    Text = "Of course, something like this is very strange!!!"
  },
  AvgCommunicate_95004_Option_9 = {
    Text = "It's very strange!!"
  },
  AvgCommunicate_95005_Content_1 = {
    Text = "Friends who perform rituals frequently already know this."
  },
  AvgCommunicate_95005_Content_10 = {
    Text = "Do you think anyone will actually fall for this scheme of ours?"
  },
  AvgCommunicate_95005_Content_11 = {
    Text = "What if they do? After all, who knows what cultists are thinking?"
  },
  AvgCommunicate_95005_Content_12 = {
    Text = "Wouldn't it be better to have Ryker help you out?"
  },
  AvgCommunicate_95005_Content_13 = {
    Text = "With his luck, he might actually reel in quite a few cultists."
  },
  AvgCommunicate_95005_Content_14 = {
    Text = "No need. I just wanted to hear the little one say those words."
  },
  AvgCommunicate_95005_Content_15 = {
    Text = "?! Is this some kind of specialized roleplay?!"
  },
  AvgCommunicate_95005_Content_16 = {
    Text = "The date for the action will be announced later. I'll see you then, little one."
  },
  AvgCommunicate_95005_Content_2 = {
    Text = "It's easy to gather the offerings, but hard to invite the divine."
  },
  AvgCommunicate_95005_Content_3 = {
    Text = "Therefore, a successful invocation often requires multiple modifications to the sacrifice and adjustments to the ritual circle."
  },
  AvgCommunicate_95005_Content_4 = {
    Text = "Here, we use a secret brew of blood, supplemented by seven hundred seventy-seven living corpses, placed within a specially designed summoning circle."
  },
  AvgCommunicate_95005_Content_5 = {
    Text = "This maximizes the chance of winning the deity's favor and successfully compelling their descent."
  },
  AvgCommunicate_95005_Content_6 = {
    Text = "What is the sacrificial method you use over there?"
  },
  AvgCommunicate_95005_Content_7 = {
    Text = "Could you write and tell me?"
  },
  AvgCommunicate_95005_Content_8 = {
    Text = "Please write to share your insights with us."
  },
  AvgCommunicate_95005_Content_9 = {
    Text = "That's the spirit. Not bad, little one."
  },
  AvgCommunicate_95005_Option_7 = {
    Text = "Could you write and tell me?"
  },
  AvgCommunicate_95005_Option_8 = {
    Text = "Please write to share your insights with us."
  },
  AvgCommunicate_96408_Content_1 = {
    Text = "Hey there! Specializing in corpse recycling—affordable rates, DM for inquiries! Priority given to well-preserved specimens. Nationwide shipping available!"
  },
  AvgCommunicate_96408_Content_10 = {
    Text = "Ah... A customer! As expected, I can count on that lady."
  },
  AvgCommunicate_96408_Content_11 = {
    Text = "My culinary instruments are prepared. We shall converse again shortly."
  },
  AvgCommunicate_96408_Content_12 = {Text = "..."},
  AvgCommunicate_96408_Content_13 = {
    Text = "I'll just pretend I don't know what you plan to do next."
  },
  AvgCommunicate_96408_Content_2 = {Text = "?!"},
  AvgCommunicate_96408_Content_3 = {
    Text = "Doresain... Doresain? Huh...???"
  },
  AvgCommunicate_96408_Content_4 = {
    Text = "Did you get hacked??"
  },
  AvgCommunicate_96408_Content_5 = {
    Text = "So it's {Male=Mr.,Female=Miss} Keeper, I'm trying to attract customers using the communicator."
  },
  AvgCommunicate_96408_Content_6 = {
    Text = "Did you really start sending spam the first time you used it...? Who taught you to do this...?"
  },
  AvgCommunicate_96408_Content_7 = {
    Text = "That child named Jenkin has an impressive ability to tell what other people think."
  },
  AvgCommunicate_96408_Content_8 = {
    Text = "...It's her after all."
  },
  AvgCommunicate_96408_Content_9 = {
    Text = "And compared to the arduous ascent to culinary mastery, acquiring this particular skill is hardly taxing."
  },
  AvgCommunicate_96408_Option_12 = {Text = "..."},
  AvgCommunicate_96408_Option_2 = {Text = "?!"},
  AvgCommunicate_96408_Option_3 = {Text = "Doresain?"},
  AvgCommunicate_96408_Option_4 = {
    Text = "Uh... Your account got hacked?"
  },
  AvgCommunicate_96408_Option_6 = {
    Text = "Customer..."
  },
  AvgCommunicate_96408_Option_8 = {Text = "Jenkin!"},
  AvgCommunicate_96409_Content_1 = {
    Text = "Dear Keeper, may I have the honor to invite you over for dinner tonight?"
  },
  AvgCommunicate_96409_Content_10 = {
    Text = "I used my newly created sauce for this meal."
  },
  AvgCommunicate_96409_Content_11 = {
    Text = "Would you like to try it, {Male=Mr.,Female=Miss} Keeper?"
  },
  AvgCommunicate_96409_Content_12 = {
    Text = "Thank you for your kindness..."
  },
  AvgCommunicate_96409_Content_13 = {
    Text = "Thank you for your kindness..."
  },
  AvgCommunicate_96409_Content_14 = {
    Text = "But I had an upset stomach last night, so I'm afraid I won't be able to enjoy it."
  },
  AvgCommunicate_96409_Content_15 = {
    Text = "Is that right? That's too bad."
  },
  AvgCommunicate_96409_Content_16 = {
    Text = "How many times have you gotten a stomachache from eating something bad?"
  },
  AvgCommunicate_96409_Content_17 = {Text = "Uh..."},
  AvgCommunicate_96409_Content_18 = {
    Text = "Never having tasted the delicacy of a fresh corpse is truly a pity. I hope you will seriously consider my invitation."
  },
  AvgCommunicate_96409_Content_19 = {
    Text = "Next time, definitely next time."
  },
  AvgCommunicate_96409_Content_2 = {
    Text = "I tried making a garlic-scented shoulder bone dish with spinal marrow mud salad. It was tender, flavorful, and carried a subtle sense of Lingering Warmth from Childhood Trauma."
  },
  AvgCommunicate_96409_Content_3 = {
    Text = "Hmm... It sounds like the kind of smell that would leave lasting psychological scars."
